window.DEMO_TEST = {"schemaVersion":1,"testType":"full","id":"cat-studio-demo","revision":1,"title":"Explore the exam experience","demo":true,"description":"A short, original sample across all three sections. Try the tools before a real attempt.","sections":[{"code":"VARC","groups":[{"id":"demo-rc","title":"RC · Learning through retrieval","stimulus":"Students often judge learning by how familiar a page feels on a second reading. Yet familiarity can conceal gaps in recall. A learner who closes the book and tries to explain an idea may feel less fluent, but the effort reveals what remains uncertain.\n\nThis does not make rereading useless. A return to the text after an attempted explanation can target specific gaps. The distinction is between rereading to avoid effort and rereading to answer a question that effort has exposed.","questions":[{"id":"demo-v1","type":"MCQ","prompt":"Which statement best captures the central argument?","options":[{"id":"A","text":"Rereading always harms recall."},{"id":"B","text":"Fluency is a reliable measure of understanding."},{"id":"C","text":"Attempting recall can reveal gaps that targeted rereading then addresses."},{"id":"D","text":"Books should be closed permanently after one reading."}],"answer":"C","topic":"Reading comprehension","explanation":"The author combines effortful recall with targeted rereading rather than rejecting rereading."},{"id":"demo-v2","type":"MCQ","prompt":"The author would most likely recommend:","options":[{"id":"A","text":"Explaining an idea without the text, then checking uncertain points."},{"id":"B","text":"Reading a page until every word feels familiar."},{"id":"C","text":"Avoiding difficult explanations."},{"id":"D","text":"Measuring learning only by reading speed."}],"answer":"A","topic":"Reading comprehension","explanation":"This sequence follows the method described in the second paragraph."}]},{"id":"demo-va","title":"Verbal ability","questions":[{"id":"demo-v3","type":"TITA","prompt":"Arrange the sentences into a coherent paragraph. Enter the sequence.\n\n1. This stored water supports the seedlings during dry weeks.\n2. Farmers first collect rainwater in small tanks.\n3. They then channel the stored water towards newly planted beds.","answer":["231"],"topic":"Para jumble","explanation":"Collection comes first, channeling follows, and the final sentence explains the benefit."}]}]},{"code":"DILR","groups":[{"id":"demo-di","title":"DI · Bookshop sales","stimulus":"A bookshop sold the following numbers of books.\n\n             Monday   Tuesday\nFiction        30        45\nScience        20        25\nHistory        10        20\n\nAll figures are numbers of books, not sales revenue.","questions":[{"id":"demo-d1","type":"TITA","prompt":"How many books were sold on Tuesday?","answer":["90"],"topic":"Tables","explanation":"45 + 25 + 20 = 90."},{"id":"demo-d2","type":"MCQ","prompt":"Which category had the largest percentage increase from Monday to Tuesday?","options":[{"id":"A","text":"Fiction"},{"id":"B","text":"Science"},{"id":"C","text":"History"},{"id":"D","text":"All three were equal"}],"answer":"C","topic":"Tables","explanation":"History doubled from 10 to 20, an increase of 100%."},{"id":"demo-d3","type":"TITA","prompt":"What percentage of Monday sales consisted of fiction books?","answer":["50"],"topic":"Tables","explanation":"30 out of 60 books is 50%."}]}]},{"code":"QA","groups":[{"id":"demo-qa1","title":"Arithmetic","questions":[{"id":"demo-q1","type":"MCQ","prompt":"A price rises by 20% and then falls by 20%. What is the net change?","options":[{"id":"A","text":"No change"},{"id":"B","text":"4% decrease"},{"id":"C","text":"4% increase"},{"id":"D","text":"2% decrease"}],"answer":"B","topic":"Percentages","explanation":"100 × 1.2 × 0.8 = 96, a decrease of 4%."}]},{"id":"demo-qa2","title":"Algebra","questions":[{"id":"demo-q2","type":"TITA","prompt":"If 3x + 7 = 34, find x.","answer":["9"],"topic":"Linear equations","explanation":"Subtract 7 and divide by 3: x = 27 / 3 = 9."}]},{"id":"demo-qa3","title":"Arithmetic","questions":[{"id":"demo-q3","type":"MCQ","prompt":"A train covers 180 km in 3 hours. What is its average speed?","options":[{"id":"A","text":"45 km/h"},{"id":"B","text":"50 km/h"},{"id":"C","text":"60 km/h"},{"id":"D","text":"90 km/h"}],"answer":"C","topic":"Speed and distance","explanation":"Speed = distance / time = 180 / 3 = 60 km/h."}]}]}]};
window.BUNDLED_TESTS = [{"schemaVersion":1,"id":"ims-varc-section-6-2026","revision":2,"title":"VARC Section Test 6 · 2026","description":"24 questions · 4 RC passages + 8 verbal ability questions. Extracted from your ZIP.","source":{"archive":"VA sectional 6.zip","imageCount":24,"answerKey":"Green correct-option markers and explicit TITA answer fields in supplied review screenshots.","explanations":"Not present in the supplied screenshots.","reviewStatus":"Text and answer keys reviewed against source screenshots."},"sections":[{"code":"VARC","groups":[{"id":"va6-rc1","title":"RC · Psychiatric diagnosis","stimulus":"The work of the German psychiatrist Emil Kraepelin in the late-19th and early 20th century - which separated mood disorders from psychotic ones - laid the foundations for the reference manuals used today by all psychiatrists to diagnose hundreds of different mental disorders, each grouped into 20 or so categories.\n\nPsychiatric diagnosis helps select the right treatment for a person's symptoms. Standardized diagnosis makes it possible to track and map the occurrence of a disorder across time and space, a field known as ‘psychiatric epidemiology’. However, while other branches of medicine have drastically reduced mortality rates from diseases or disorders of the body, there haven't been similar successes in mental healthcare. Psychiatry appears to be stuck. Perhaps because the diagnostic system is faulty. Indeed, the fact that around half of patients with one mental disorder also fulfil the requirement for a second disorder has been well documented since the 1990s. Either mental disorders really tend to aggregate or, perhaps more likely and more worryingly, our classification system is drawing the borders wrong.\n\nThankfully, an alternative approach to psychiatric diagnosis already exists. A growing troupe of scientists think that focusing on one or two diagnoses in a study - as is common in psychiatric research - has allowed the true nature of mental disorders remains hidden. They argue that we have to zoom out before we can properly understand what essentially are brain disorders, because the different parts of the brain are interconnected in very complex ways. Considering the whole spectra of psychiatric possibilities at once can reveal similarities in symptoms, brain circuitry and genetics. Belying the diagnostic classification, there is growing evidence that all mental disorders are actually the product of a single underlying factor, a common vulnerability to psychopathology. Known as the ‘p-factor’, this theoretical concept brings the potential for important new ways to treat and prevent psychiatric disorders. It also raises the possibility that psychiatric patients suffering different things actually share the same underlying vulnerability, but certain life experiences have influenced the way it manifests.\n\nNeedless to say, the p-factor is a recent concept. The paper most often cited as its foundation was published in 2012 by Benjamin Lahey, a psychologist from the University of Chicago, and his colleagues. Studying the symptoms and prognosis of 11 mental disorders in 30,000 people, they found that the distribution of diagnoses was captured largely by two groupings or dimensions familiar to child psychiatry since the 1960s: internalizing (inward looking and separated into fear and distress) and externalizing (outward and sometimes explosive, including substance use, conduct disorder, and ADHD). Crucially, even the disorders categorized as internalizing or externalizing often overlapped with one another.\n\nQuite logically, we may expect people who experience one fear to experience other fears and for people who worry to be unhappy. Yet we don't think it very likely that antisocial individuals who abuse drugs also worry and remain fearful, sad and guilt-ridden but that was exactly what the data collected by Lahey and his colleagues implied. And the statistical model that best explained the data implied a ‘higher order’ vulnerability factor that these two categories of mental disorders shared. When this factor was removed from the models, the correlations between the groups became weaker, suggesting that it was responsible for the frequent co-occurrence of externalizing and internalizing disorders.","questions":[{"id":"va6-q01","sourceNumber":1,"type":"MCQ","prompt":"Which of the following evaluations of Emil Kraepelin's work will the author of this passage most agree with?","answer":"C","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111405.png"],"options":[{"id":"A","text":"Kraepelin's influence has exerted a negative influence on the growth of psychiatry."},{"id":"B","text":"Kraepelin should not have considered mood disorders fundamentally different from psychotic ones."},{"id":"C","text":"Kraepelin's work had a major impact on modern psychiatry and its understanding of mental illnesses and treatments."},{"id":"D","text":"Kraepelin's work, despite its limitations, pioneered the alternative approach to psychiatric diagnosis that exists today."}],"area":"Reading Comprehension","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":293,"topperAttemptPercent":90.77,"topperAccuracyPercent":81.36,"topperPValue":73.85}},{"id":"va6-q02","sourceNumber":2,"type":"MCQ","prompt":"According to the author, why did psychiatry ‘appear to be stuck’ (2nd paragraph)?","answer":"C","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111416.png"],"options":[{"id":"A","text":"Psychiatric diagnosis did not help doctors to correctly treat the symptoms."},{"id":"B","text":"Psychiatry failed to reduce the mortality rates from mental disorders."},{"id":"C","text":"The practice of its century old diagnostic system hindered its progress."},{"id":"D","text":"Psychiatric epidemiology prevented advancements in psychiatric therapy."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":76,"topperAttemptPercent":90.77,"topperAccuracyPercent":47.46,"topperPValue":43.08}},{"id":"va6-q03","sourceNumber":3,"type":"MCQ","prompt":"According to the passage, Emil Kraepelin's diagnosis system ...","answer":"B","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111423.png"],"options":[{"id":"A","text":"helped cure some of the mental disorders."},{"id":"B","text":"helped the study of the social risk factors of mental disorders."},{"id":"C","text":"was ineffective in reducing the intensity of the symptoms."},{"id":"D","text":"succeeded in suggesting the aggregation of mental disorders."}],"area":"Reading Comprehension","selectionCategory":"C","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":63,"topperAttemptPercent":73.85,"topperAccuracyPercent":12.5,"topperPValue":9.23}},{"id":"va6-q04","sourceNumber":4,"type":"MCQ","prompt":"All of the following statements are true about the p-factor EXCEPT:","answer":"A","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111431.png"],"options":[{"id":"A","text":"It is the fundamental principle used to diagnose hundreds of different mental disorders."},{"id":"B","text":"It is a general dormant factor derived from a range of psychiatric symptoms."},{"id":"C","text":"It is a single factor that can summarize an individuals’ tendency to develop all forms of mental disorders."},{"id":"D","text":"All internalizing and externalizing disorders are a product of the p-factor."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":82,"topperAttemptPercent":80,"topperAccuracyPercent":55.77,"topperPValue":44.62}}]},{"id":"va6-rc5","title":"RC · Venture capital","stimulus":"The economics profession has long recognized two great institutions of modern capitalism: markets and companies. Markets coordinate activity via price signals and arm's-length contracts. Companies coordinate by assembling large teams led by top-down managers. But economists have focused less on the middle ground that venture capital inhabits.\n\nVenture capitalists (VCs) channel capital, advice and talented recruits to promising start-ups; in this way, they replicate the managerial direction and team formation found in corporations. At the same time, venture capitalists have the flexibility of the market. They can get behind a start-up with a fresh business idea; they can shape it, expand it, murmur its name into the right ears. But when a round of funding is exhausted, the market will decide what happens. If there are no enthusiastic buyers for the next tranche of the start-up's equity, it will be forced to close, avoiding the waste of resources that comes from sticking with doomed speculative ventures. This blend of corporate strategizing and respect for the market represents a third great institution of modern capitalism, to be added to the two that economists traditionally emphasize.\n\n... A huge amount of energy in government and the private sector is spent on economic forecasting; without a clear view of the future, committing resources would seem irresponsible. But extrapolations from past data anticipate the future only when there is not much to anticipate; if tomorrow will be a mere extension of today, why bother with forecasting? ...The big disruptions that create extreme wealth for inventors and great anxiety for workers cannot be foretold because they are so thoroughly disruptive. Rather, they will emerge from the murky soup of tinkerers and hackers and hubristic dreamers, and all you can know is that in 10 years the world will be excitingly different. The future can be discovered by means of iterative, venture-backed experiments. It cannot be predicted.\n\n[But ...] the very success of the industry has attracted incautious investors who shower money on young companies without overseeing their founders. The result is multibillion-dollar “unicorns” with inadequate governance. In a few celebrated cases ... entrepreneurs who thought themselves accountable to nobody cut ethical corners, with investors, employees and customers alike paying the price. The underrepresentation of women and minorities is another failing. ... An industry that involves subjective judgments about start-up founders is wide open to bias and should stress diversity all the more. Without progress on this front, people of a certain type will fund people of a similar type. The venture industry is a meritocracy, up to a point. It is also what its critics call a “mirror-tocracy.”\n\nDespite these reservations, venture capital is a positive force for societies and economies. Only a fraction of 1 percent of firms in the United States receive venture-capital backing, yet this tiny minority accounts for fully 47 percent of the nonfinancial companies that do well enough to go public and 76 percent of the market capitalization of these firms. Venture-backed companies have delivered more progress in applied science than any kind of rival: more than centralized corporate research and development units, more than isolated individuals tinkering in garages and more than government attempts to pick technological winners.","questions":[{"id":"va6-q05","sourceNumber":5,"type":"MCQ","prompt":"What is this passage about?","answer":"D","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111440.png"],"options":[{"id":"A","text":"Economists’ failure to accept venture capital as an institution of modern capitalism."},{"id":"B","text":"The institutions upon which the modern capitalist system is built."},{"id":"C","text":"Development of modern capitalism as an outcome of markets and companies."},{"id":"D","text":"Venture-backed experiments as an institution of modern capitalist system."}],"area":"Reading Comprehension","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":253,"topperAttemptPercent":87.69,"topperAccuracyPercent":96.49,"topperPValue":84.61}},{"id":"va6-q06","sourceNumber":6,"type":"MCQ","prompt":"All of the following can be inferred from Paragraph 2 EXCEPT:","answer":"B","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111448.png"],"options":[{"id":"A","text":"Start-ups look to VCs for the funding to scale and commercialize their products or services."},{"id":"B","text":"Venture capitalists normally channel capital into new companies from the onset."},{"id":"C","text":"VCs choose start-ups in industries in which they can influence its direction."},{"id":"D","text":"Venture Capital complements both company management and markets."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":85,"topperAttemptPercent":86.15,"topperAccuracyPercent":37.5,"topperPValue":32.31}},{"id":"va6-q07","sourceNumber":7,"type":"MCQ","prompt":"According to the author, economic forecasting does not hold much value for all the following reasons EXCEPT:","answer":"B","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111454.png"],"options":[{"id":"A","text":"Forecasts assume economic processes are stationary and continuous."},{"id":"B","text":"Those who indulge in economic forecasting lack a clear view of the future."},{"id":"C","text":"Disruptive wealth creation happens through trial and error methods."},{"id":"D","text":"Economic forecasts will never be spot on."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":72,"topperAttemptPercent":81.54,"topperAccuracyPercent":50.94,"topperPValue":41.54}},{"id":"va6-q08","sourceNumber":8,"type":"MCQ","prompt":"The author of the passage is most likely to support which one of the following statements?","answer":"C","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111500.png"],"options":[{"id":"A","text":"Start-ups backed by VCs are more likely to succeed than others."},{"id":"B","text":"Most start-ups fail, with the result that VCs end up with worthless equity."},{"id":"C","text":"VCs fund start-ups whose earnings exist only in an imagined future."},{"id":"D","text":"Venture backed start-ups are more successful in technology than in others."}],"area":"Reading Comprehension","selectionCategory":"C","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":58,"topperAttemptPercent":86.15,"topperAccuracyPercent":21.43,"topperPValue":18.46}}]},{"id":"va6-rc9","title":"RC · Evidence and authority","stimulus":"As schoolchildren, we learn that different weights fall at the same speed. This simple and readily tested observation, first published by Galileo, refuted Aristotle, who claimed that heavy things fall faster. As Galileo put it, ‘I greatly doubt that Aristotle ever tested by experiment whether it be true.’ We are left to wonder how people could have believed what they were told, and for two millennia at that, without ever checking? Surely the power of evidence over authority is obvious.\n\nExcept it isn’t. Even today, evidence has barely begun to upend authority; the world is still more in thrall to Aristotle than Galileo. As a simple example, the time-honoured advice for those suffering from bad backs has been bed rest. Only recently, though, have we discovered bed rest isn't the best treatment, and isn't even particularly good compared to moderate activity. How did this discovery come about? A researcher in the field of Evidence-based Medicine surveyed multiple databases of trials and results for patients with back pain. (It tells us something about medicine's current form that we even need a term like Evidence-based Medicine.) And why did it take so long to look at the evidence? Same reason it took so long to question Aristotle: some doctor in the distant past reasoned that bed rest would be a good idea, and it became the authoritative and little-questioned view.\n\nIn school, the embrace of evidence is often taught as if it were a one-time revolution that has now been internalized by society. It hasn't. The idea of evidence is consistently radical: Take nothing on faith. No authority is infallible. If you figure out a good way to test something, you can contradict hallowed figures with impunity.\n\nEvidence will continue to improve society, but slowly - this is long-view optimism. The use of evidence dragged the curious mind from the confusion of alchemy into the precision of chemistry in the historical blink of an eye, but its progress past the hard sciences has been considerably slower. Even accepting that evidence should shape our views is inconsistent with much human behaviour. Everything from the belief in supernatural beings to deference to elders pushes against the idea that a single person, if he or she comes to understand the evidence, should be allowed to upend a millennium of cherished human belief.\n\nIt is only in the last hundred years that evidence has even begun spreading from the hard sciences into other parts of human life. Previous platitudes about the unpredictability or universal plasticity of human behaviour are giving way to areas of inquiry with names like Sociobiology, Evolutionary Psychology, and Behavioural Economics. (That we need a label like Behavioural Economics says as much about economics as Evidence-based Medicine does about medicine.) As reliance on evidence spreads, it takes with it an understanding of how it works.\n\nSocial science is expanding because we are better about gathering data and about understanding it. We have gone from a drought to a flood of data about personal and social behaviour in the last generation. We will learn more about the human condition in the next two decades than we did in the last two millennia, and we will then begin to apply what we learn, everywhere. Evidence-based treaties. Evidence-based teaching. Evidence-based industrial design. Evidence-based parenting.","questions":[{"id":"va6-q09","sourceNumber":9,"type":"MCQ","prompt":"The author provides the example of bad backs in order to:","answer":"C","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111510.png"],"options":[{"id":"A","text":"Show that bed rest is not the best treatment for them."},{"id":"B","text":"Prove that moderate activity is the best treatment for them."},{"id":"C","text":"Explain that blindly trusting authority led to a suboptimal treatment for them."},{"id":"D","text":"Point out that aversion to evidence results in ignoring age-old advice."}],"area":"Reading Comprehension","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":205,"topperAttemptPercent":92.31,"topperAccuracyPercent":100,"topperPValue":92.31}},{"id":"va6-q10","sourceNumber":10,"type":"MCQ","prompt":"What can be inferred about Galileo's attitude towards Aristotle, based on this passage?","answer":"A","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111520.png"],"options":[{"id":"A","text":"He speculated that Aristotle never actually tested his theory."},{"id":"B","text":"He was surprised to learn that Aristotle never actually tested his theory."},{"id":"C","text":"He mocked Aristotle for never actually testing his theory."},{"id":"D","text":"He refused to believe that Aristotle never actually tested his theory."}],"area":"Reading Comprehension","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":45,"topperAttemptPercent":87.69,"topperAccuracyPercent":89.47,"topperPValue":78.46}},{"id":"va6-q11","sourceNumber":11,"type":"MCQ","prompt":"What is the author's opinion of evidence?","answer":"B","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111825.png"],"options":[{"id":"A","text":"He admires the fact that it revolutionized society."},{"id":"B","text":"He is pleased about its iconoclastic and progressive abilities."},{"id":"C","text":"He is optimistic about the power of evidence, but advocates using it with caution."},{"id":"D","text":"He respects its importance, but worries that it will upend cherished beliefs."}],"area":"Reading Comprehension","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":53,"topperAttemptPercent":84.62,"topperAccuracyPercent":76.36,"topperPValue":64.62}},{"id":"va6-q12","sourceNumber":12,"type":"MCQ","prompt":"Which of these statements would the author agree with?","answer":"A","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111533.png"],"options":[{"id":"A","text":"Deference to elders is incompatible with a belief in evidence."},{"id":"B","text":"Human beings are hard-wired to accept the insights provided by evidence."},{"id":"C","text":"New social sciences are unearthing evidence regarding the universal plasticity of human behaviour."},{"id":"D","text":"As vitally important as evidence is, there are some areas of life where it is not very useful."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":67,"topperAttemptPercent":83.08,"topperAccuracyPercent":61.11,"topperPValue":50.77}}]},{"id":"va6-va13","title":"Para summary","questions":[{"id":"va6-q13","sourceNumber":13,"type":"MCQ","prompt":"Four alternative summaries are given below each text. Choose the option that best captures the essence of the text.\n\nAuto manufacturers have often seen that a car model name that works well in one country must be modified to have success in another. Ford launched a car in Europe named Kuga, which means ‘plague’ in Croatian and Serbian. Mitsubishi produced an off-road vehicle called the Pajero, an offensive term in some Spanish-speaking countries. The Honda Fitta had to be renamed to the Honda Jazz for the Nordic market because fitta is a profane word in Nordic languages. One car that didn't have to be renamed? The Chevy Nova. Contrary to popular belief, the word nova is not easily confused with the words no va (doesn't go) in Spanish because they are pronounced differently, with stress on different syllables. General Motors reported that the Nova actually surpassed its expectations for sales in Spanish-speaking markets such as Venezuela.","answer":"C","topic":"Para summary","sourceImages":["Screenshot 2026-10-12 111600.png"],"options":[{"id":"A","text":"Sometimes cars have names that have unfortunate meanings in other languages, so these have to be changed depending on the markets, for example, the Chevy Nova."},{"id":"B","text":"Unlike many other cars, whose names have to be changed in international markets, the Chevy Nova's name did not have to be changed, though it is an offensive term in some Spanish-speaking countries."},{"id":"C","text":"A number of car names have to be modified in different countries, because they don't translate well into the local languages, but surprisingly enough, the Chevy Nova is not one of them."},{"id":"D","text":"Most cars have to be renamed for the international market, as they have names that have negative connotations in the local languages - for example, a car whose name translates to ‘doesn't go’ in Spanish."}],"area":"Verbal Reasoning","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (6).png","topperTimeSeconds":87,"topperAttemptPercent":87.69,"topperAccuracyPercent":92.98,"topperPValue":81.53}}]},{"id":"va6-va14","title":"Para summary","questions":[{"id":"va6-q14","sourceNumber":14,"type":"MCQ","prompt":"The passage given below is followed by four summaries. Choose the option that best captures the essence of the passage.\n\nPlaywright George Bernard Shaw has a reputation as a humanitarian, an indefatigable seeker of justice and, in his own words, a ‘world betterer.’ But this reputation is difficult to reconcile with his support for the totalitarian regimes and dictators that emerged after the First World War, which is not so well known. This enthusiasm is usually dismissed as an expression of Shaw's well-known propensity for comic exaggeration and hyperbole, his pugnacious rhetoric, his love of paradox, and especially his addiction to antagonizing the British political establishment. However, as I believe this dissertation proves, Shaw's support was genuine, rooted in his powerful desire for absolute control over the unruly and chaotic, in a deep psychological longing for perfection. Shaw expressed rigid control over his own bodily instincts, and looked for political rulers of strong will and utopian designs to exercise similar control over unruly social elements.","answer":"A","topic":"Para summary","sourceImages":["Screenshot 2026-10-12 111606.png"],"options":[{"id":"A","text":"Although George Bernard Shaw is widely seen as a humanitarian, his genuine support for totalitarian regimes reveals a deeper psychological desire for strict control and perfection in both personal and social order."},{"id":"B","text":"Playwright George Bernard Shaw sincerely supported authoritarian regimes due to a deep psychological desire for absolute control and social perfection."},{"id":"C","text":"Although George Bernard Shaw is widely regarded as a humanitarian, his support for totalitarian regimes is often seen as rhetorical exaggeration, overlooking the deeper psychological motives behind his attraction to strong control and order."},{"id":"D","text":"Although George Bernard Shaw is widely viewed as a humanitarian, his support for totalitarian regimes is often attributed to his provocative style and love of paradox."}],"area":"Verbal Reasoning","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":106,"topperAttemptPercent":76.92,"topperAccuracyPercent":50,"topperPValue":38.46}}]},{"id":"va6-va15","title":"Odd sentence out","questions":[{"id":"va6-q15","sourceNumber":15,"type":"TITA","prompt":"Five sentences related to a topic are given below. Four of them can be put together to form a meaningful and coherent short paragraph. Identify the odd one out. Choose its number as your answer and key it in.\n\n1. The key to music is that these pulls can be resisted, and it is the job of the musician to know when and how to do so.\n\n2. The effect of a tune is determined by whether it follows the attractions or resists them.\n\n3. Music theorists say that notes higher in this hierarchy are more stable, by which they mean that they seem less likely to move off somewhere else.\n\n4. If there were no underlying tendencies, no implications within each note of which one will follow, we would be indifferent to the outcome, and all melodies would sound like the same random meandering.\n\n5. If music was simply a matter of following gravity-like attractions from note to note, there would be nothing for the composer to do: a melody would be as inevitable as the path of water rushing down a mountainside.","answer":["3"],"topic":"Odd sentence out","sourceImages":["Screenshot 2026-10-12 111614.png"],"area":"Verbal Reasoning","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":106,"topperAttemptPercent":90.77,"topperAccuracyPercent":72.88,"topperPValue":66.15}}]},{"id":"va6-va16","title":"Odd sentence out","questions":[{"id":"va6-q16","sourceNumber":16,"type":"TITA","prompt":"Five sentences related to a topic are given below. Four of them can be put together to form a meaningful and coherent short paragraph. Identify the odd one out. Choose its number as your answer and key it in.\n\n1. Standards, customs and agricultural practices varied greatly across the country, depending on natural conditions and patterns of land ownership and management.\n\n2. At this point in time, Ireland was a kingdom with its own legislature and officials, but its autonomy was undermined by its dependence on Great Britain, the senior partner in the constitutional relationship between the islands.\n\n3. Ireland in the 18th century was an overwhelmingly rural society whose strong regional variations nurtured a diversity of political, social and economic cultures.\n\n4. On the other hand, some pronounced themselves surprised by the existence of forward-thinking landlords and industrialists in Ireland.\n\n5. Visitors to the country generally agreed that by British standards, Irish farming practices were backward.","answer":["2"],"topic":"Odd sentence out","sourceImages":["Screenshot 2026-10-12 111621.png"],"area":"Verbal Reasoning","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":91,"topperAttemptPercent":92.31,"topperAccuracyPercent":61.67,"topperPValue":56.93}}]},{"id":"va6-va17","title":"Para jumble","questions":[{"id":"va6-q17","sourceNumber":17,"type":"TITA","prompt":"The four sentences (labelled 1, 2, 3, 4) given below, when properly sequenced would yield a coherent paragraph. Decide on the proper sequence of the order of the sentences and key in the sequence of the four numbers as your answer.\n\n1. These in turn were in an ideal position to send colonists onto dry land when another blowout in the late Devonian period gave life another sound shaking.\n\n2. The Ordovician extinction of 440 million years ago cleared the oceans of a lot of immobile filter feeders and, somehow, created conditions that favored darting fish and giant aquatic reptiles.\n\n3. Crises in Earth's history are invariably associated with dramatic leaps afterward.\n\n4. The fall of the Ediacaran fauna was followed by the creative outburst of the Cambrian period.","answer":["3421"],"topic":"Para jumble","sourceImages":["Screenshot 2026-10-12 111628.png"],"area":"Verbal Reasoning","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":85,"topperAttemptPercent":83.08,"topperAccuracyPercent":59.26,"topperPValue":49.23}}]},{"id":"va6-va18","title":"Para jumble","questions":[{"id":"va6-q18","sourceNumber":18,"type":"TITA","prompt":"The four sentences (labelled 1, 2, 3, 4) given below, when properly sequenced would yield a coherent paragraph. Decide on the proper sequence of the order of the sentences and key in the sequence of the four numbers as your answer.\n\n1. English is one of about a dozen languages that are all so basically similar in terms of words and grammar, and mostly spoken so close to one another, that they all obviously began as a single language (although English is very much a prodigal son).\n\n2. We will never know what the people who spoke that language called it, but linguists call it Proto-Germanic.\n\n3. The parent to all of these languages was spoken about twenty-five hundred years ago in what is now Denmark (and a ways southward) and on the southerly ends of Sweden and Norway.\n\n4. The languages besides English include German, Dutch, Yiddish, Swedish, Norwegian, Danish and Icelandic, plus some less familiar languages, like Faroese and Frisian, and Afrikaans in South Africa, which stemmed from the transplantation of Dutch amid the colonization of that country.","answer":["1432"],"topic":"Para jumble","sourceImages":["Screenshot 2026-10-12 111634.png"],"area":"Verbal Reasoning","selectionCategory":"A","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":91,"topperAttemptPercent":78.46,"topperAccuracyPercent":88.24,"topperPValue":69.23}}]},{"id":"va6-va19","title":"Sentence placement","questions":[{"id":"va6-q19","sourceNumber":19,"type":"MCQ","prompt":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3, or 4) the following sentence would best fit.\n\nSentence: Novels and short stories about ghosts and witches (and reviews of such works), as well as public lectures, are similarly indicative of changing attitudes towards customary magic among the cultivated and the literate.\n\nParagraph: An investigation into the occult mind of the middle orders is challenging because the conventional ethnographic sources—newspapers, antiquarian studies, and folk lore reports—tend to have a voyeur's preoccupation with the mores of poor, illiterate, and rustic people. __(1)__. Yet on closer inspection, these sources, through their self-justifications, editorial conventions, and changing subject matter, also reveal much about the outlook of their well-to-do authors and audiences. __(2)__. These sources suggest that neither the Enlightenment nor modernization gradually freed the middle classes from the grip of customary magic. Rather, larger numbers continued to endorse its reality for much longer than we might imagine, before rapidly, dramatically, but also temporarily, disowning it. __(3)__. Not until the 1820s and 1830s was belief in witchcraft, ghosts, and divination perceived as scandalous, both in polite literature and in ‘respectable’ society. __(4)__. Redefined as ‘popular superstitions,’ from the 1820s to the 1860s customary occult beliefs generated particular alarm and were subjected to unprecedented opprobrium.","answer":"B","topic":"Sentence placement","sourceImages":["Screenshot 2026-10-12 111643.png"],"options":[{"id":"A","text":"Option 1"},{"id":"B","text":"Option 2"},{"id":"C","text":"Option 3"},{"id":"D","text":"Option 4"}],"area":"Verbal Reasoning","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":114,"topperAttemptPercent":61.54,"topperAccuracyPercent":57.5,"topperPValue":35.39}}]},{"id":"va6-va20","title":"Sentence placement","questions":[{"id":"va6-q20","sourceNumber":20,"type":"MCQ","prompt":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3, or 4) the following sentence would best fit.\n\nSentence: While Western medical science sees the human body as a material thing that can be understood by examining it, Heidegger's ontology puts human experience at the centre of our understanding of the world.\n\nParagraph: __(1)__. Heidegger pointed out that we who are asking questions about Being are qualitatively different to the rest of existence: the rocks, oceans, trees, birds and insects that we are asking about. __(2)__. He invented a special word for this Being that asks, looks and cares. He called it Dasein, which loosely translates as ‘being there’. He coined the term Dasein because he believed that we had become immune to words such as ‘person’, ‘human’ and ‘human being’, losing our sense of wonder about our own consciousness. __(3)__. Heidegger's philosophy remains attractive to many today who see how science struggles to explain the experience of being a moral, caring person aware that his precious, mysterious, beautiful life will, one day, come to an end. According to Heidegger, this awareness of our own inevitable demise makes us, unlike the rocks and trees, hunger to make our life worthwhile, to give it meaning, purpose and value. __(4)__.","answer":"D","topic":"Sentence placement","sourceImages":["Screenshot 2026-10-12 111650.png"],"options":[{"id":"A","text":"Option 1"},{"id":"B","text":"Option 2"},{"id":"C","text":"Option 3"},{"id":"D","text":"Option 4"}],"area":"Verbal Reasoning","selectionCategory":"C","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":61,"topperAttemptPercent":63.08,"topperAccuracyPercent":7.32,"topperPValue":4.62}}]},{"id":"va6-rc21","title":"RC · Public monuments and racism","stimulus":"Before the Gateway Arch went up in St. Louis in 1965, a bronze equestrian monument outside of the city's leading art museum was arguably its most recognisable symbol. Installed in 1906, the Apotheosis of St. Louis depicts the city's namesake, Louis IX of France, riding astride an armoured horse, his sword raised upside down to form a cross. It is a portrayal befitting a ruler renowned for his military prowess. However, the statue fails to address the canonised king's darker legacy—the totality of his accomplishments —and now, amid a spate of protests against systemic racism in the United States, the St. Louis monument is one of many public works at the centre of a significant cultural reckoning.\n\nIn recent years, events including white supremacist Dylann Roof’s June 2015 killing of nine church members in South Carolina, as well as a neo-Nazi’s attack on counter-protesters at a white nationalist rally in Virginia, have refocused attention on the prevalence—and meaning—of the memorials that dot the American landscape. Throughout, scholars and politicians alike had highlighted the importance of understanding why and when these statues were erected. A majority of the public has, in just the past few weeks, begun supporting the removal of these statues, and they have slowly begun to fall.\n\nAs protesters expand their focus to other controversial memorials across the country, it has become all the more apparent that this conversation is not merely about the Confederacy, but what values the nation chooses to commemorate and celebrate in public. Statues of Christopher Columbus are falling as protesters cite his role in the genocide of America’s Native populations. Moreover, in St. Louis, groups are clashing over whether to remove the statue of the monarch who lends the city its name.\n\nLouis IX reigned over France in the middle of the 13th century. Like most medieval sovereigns, he implemented legal reforms and provided charity to the Christian poor. More significantly, Louis personally led two Crusades to North Africa against Muslims. These campaigns were simply a brief chapter in a much larger drama that saw Christians wage holy war throughout the Mediterranean world against Muslims, Jews, and sometimes their fellow Christians.\n\nBoth of Louis IX's Crusades failed spectacularly, with the king captured by the Egyptians and ransomed for an enormous sum in 1250 and dying of dysentery almost immediately after that. Louis was canonized—largely for these efforts—in 1297. During the occasion, Pope Boniface VIII justified his sainthood by mentioning not only his care for the (Christian) poor, but his Crusades and defense of the Church against its “enemies.” Even as late as the 1830 French invasion of Algeria, Louis was held up as a model for the colonizers, primarily for his martial spirit—a Christian king fighting against non-believers. He has served as a symbol of France's glorious past ever since. So, when French trappers established a fur-trading post on Cahokia lands in 1764, they named the site in honour of two kings: Louis IX and then-sovereign Louis XV. The settlement retained the name through French, Spanish and finally American occupation.","questions":[{"id":"va6-q21","sourceNumber":21,"type":"MCQ","prompt":"Why is Apotheosis of St. Louis ‘at the centre of a significant cultural reckoning’?","answer":"C","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111703.png"],"options":[{"id":"A","text":"Apotheosis of St. Louis no longer represents the culture of the city after it was replaced in 1965 by the Gateway Arch."},{"id":"B","text":"The white supremacists and the neo-Nazis consider Apotheosis of St. Louis to be one of the controversial memorials in the city."},{"id":"C","text":"Apotheosis of St. Louis is seen to commemorate a king who provided both charity to the poor and persecuted Jews and Muslims."},{"id":"D","text":"In the backdrop of widespread racist violence in the US, scholars and politicians alike are rethinking on the significance of memorials in the city."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":171,"topperAttemptPercent":61.54,"topperAccuracyPercent":55,"topperPValue":33.85}},{"id":"va6-q22","sourceNumber":22,"type":"MCQ","prompt":"According to the passage, the recent support for the removal of the memorials has arisen mainly because:","answer":"D","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111713.png"],"options":[{"id":"A","text":"Scholars and politicians are only beginning to understand why and when these memorials were erected."},{"id":"B","text":"The white supremacists and the neo-Nazis have only recently turned their attention to the statues that dot the American landscape."},{"id":"C","text":"Recently, there has been a spate of racist attacks on minorities and violent protests against systemic racism in the United States."},{"id":"D","text":"The systemic racism in the US society has brought into focus the values that the nation should commemorate and celebrate in public."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":42,"topperAttemptPercent":61.54,"topperAccuracyPercent":80,"topperPValue":49.23}},{"id":"va6-q23","sourceNumber":23,"type":"MCQ","prompt":"All of the following are true about the protestors of racism in the US, EXCEPT:","answer":"B","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111722.png"],"options":[{"id":"A","text":"They question the relevance of several memorials across the US."},{"id":"B","text":"They object to the fact that the city is named St. Louis, after King Louis IX."},{"id":"C","text":"They believe that Columbus paved the way for the genocide of the natives."},{"id":"D","text":"They believe that racism is deep-rooted and widespread in the US society."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":30,"topperAttemptPercent":58.46,"topperAccuracyPercent":84.21,"topperPValue":49.23}},{"id":"va6-q24","sourceNumber":24,"type":"MCQ","prompt":"According to the passage, the church canonised Louis IX for all the following reasons, EXCEPT:","answer":"A","topic":"Reading comprehension","sourceImages":["Screenshot 2026-10-12 111727.png"],"options":[{"id":"A","text":"his military prowess and the legal reforms he carried out."},{"id":"B","text":"his defence of the church against the non-believers."},{"id":"C","text":"his generosity towards the Christian poor."},{"id":"D","text":"his devotion to the cause of defeating the non-believers."}],"area":"Reading Comprehension","selectionCategory":"B","benchmark":{"source":"IMS supplied analysis screenshots","sourceImage":"Screenshot (7).png","topperTimeSeconds":55,"topperAttemptPercent":60,"topperAccuracyPercent":74.36,"topperPValue":44.62}}]}]}],"testType":"sectional","sourceAnalysis":{"label":"Original IMS attempt · supplied screenshots","sourceImages":["Screenshot (4).png","Screenshot (5).png","Screenshot (6).png","Screenshot (7).png","Screenshot (8).png"],"reportedScore":1,"percentile":17.1,"percentileMapper":[{"percentile":70,"score":16,"section":"VARC"},{"percentile":85,"score":21,"section":"VARC"},{"percentile":90,"score":24,"section":"VARC"},{"percentile":95,"score":29,"section":"VARC"},{"percentile":99,"score":38,"section":"VARC"},{"percentile":99.5,"score":40,"section":"VARC"}],"questionResults":[{"questionId":"va6-q01","outcome":"Incorrect","timeSeconds":509},{"questionId":"va6-q02","outcome":"Incorrect","timeSeconds":122},{"questionId":"va6-q03","outcome":"Correct","timeSeconds":69},{"questionId":"va6-q04","outcome":"Incorrect","timeSeconds":68},{"questionId":"va6-q05","outcome":"Incorrect","timeSeconds":442},{"questionId":"va6-q06","outcome":"Incorrect","timeSeconds":85},{"questionId":"va6-q07","outcome":"Unanswered","timeSeconds":133},{"questionId":"va6-q08","outcome":"Incorrect","timeSeconds":80},{"questionId":"va6-q09","outcome":"Unanswered","timeSeconds":43},{"questionId":"va6-q10","outcome":"Correct","timeSeconds":19},{"questionId":"va6-q11","outcome":"Unanswered","timeSeconds":2},{"questionId":"va6-q12","outcome":"Unanswered","timeSeconds":3},{"questionId":"va6-q13","outcome":"Correct","timeSeconds":147},{"questionId":"va6-q14","outcome":"Unanswered","timeSeconds":33},{"questionId":"va6-q15","outcome":"Incorrect","timeSeconds":108},{"questionId":"va6-q16","outcome":"Incorrect","timeSeconds":90},{"questionId":"va6-q17","outcome":"Incorrect","timeSeconds":108},{"questionId":"va6-q18","outcome":"Incorrect","timeSeconds":45},{"questionId":"va6-q19","outcome":"Incorrect","timeSeconds":185},{"questionId":"va6-q20","outcome":"Incorrect","timeSeconds":81},{"questionId":"va6-q21","outcome":"Unanswered","timeSeconds":15},{"questionId":"va6-q22","outcome":"Unanswered","timeSeconds":0},{"questionId":"va6-q23","outcome":"Unanswered","timeSeconds":0},{"questionId":"va6-q24","outcome":"Unanswered","timeSeconds":0}],"reportedAreas":[{"label":"Overall","score":1,"count":24,"attempted":15,"correct":3,"accuracy":20,"timeLabel":"00:39","marksPerMinute":0.03,"timePerAttemptLabel":"02:40"},{"label":"Reading Comprehension","score":0,"count":16,"attempted":8,"correct":2,"accuracy":25,"timeLabel":"00:26","marksPerMinute":0,"timePerAttemptLabel":"03:19"},{"label":"Verbal Reasoning","score":1,"count":8,"attempted":7,"correct":1,"accuracy":14.29,"timeLabel":"00:13","marksPerMinute":0.08,"timePerAttemptLabel":"01:54"}],"notes":"Source question times are the exact MM:SS values in Screenshots (6) and (7). Screenshot (5) displays rounded/truncated HH:MM totals and provider-calculated averages; retain those reported values separately. Categories A/B/C are source labels, not MCQ option IDs or inferred difficulty. The original response choices and attempt date are not specified by these analysis screenshots."}},{"schemaVersion":1,"testType":"sectional","id":"ims-dilr-section-1-2026","revision":1,"title":"DILR Section Test 1 · 2026","description":"22 DILR questions across five intact sets. Transcribed from your IMS images, with supplied question benchmarks.","sections":[{"code":"DILR","groups":[{"id":"ims-dilr-section-1-2026-dilr-g01","title":"Football tournament starting points","questions":[{"id":"ims-dilr-section-1-2026-dilr-q01","sourceNumber":1,"type":"TITA","prompt":"The same points given to four teams in the beginning were ______.","answer":["3"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (19).png","topperAttemptPercent":37.14,"topperAccuracyPercent":69.23,"topperTimeSeconds":242},"area":"Logical Reasoning","topic":"Football tournament starting points"},{"id":"ims-dilr-section-1-2026-dilr-q02","sourceNumber":2,"type":"MCQ","prompt":"What were the highest points awarded to any team in the beginning of the tournament?","answer":"D","options":[{"id":"A","text":"6"},{"id":"B","text":"7"},{"id":"C","text":"8"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (20).png","topperAttemptPercent":22.86,"topperAccuracyPercent":56.25,"topperTimeSeconds":43,"topperPValue":12.86},"area":"Logical Reasoning","topic":"Football tournament starting points"},{"id":"ims-dilr-section-1-2026-dilr-q03","sourceNumber":3,"type":"MCQ","prompt":"Which team had the highest points at the end of the first round?","answer":"D","options":[{"id":"A","text":"B"},{"id":"B","text":"E"},{"id":"C","text":"G"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (21).png","topperAttemptPercent":20,"topperAccuracyPercent":92.86,"topperTimeSeconds":28,"topperPValue":18.57},"area":"Logical Reasoning","topic":"Football tournament starting points"},{"id":"ims-dilr-section-1-2026-dilr-q04","sourceNumber":4,"type":"MCQ","prompt":"If no two teams with the same starting points played against each other on any of the four days, which of the following cannot be the number of points of any team at the end of day 4?","answer":"A","options":[{"id":"A","text":"6"},{"id":"B","text":"8"},{"id":"C","text":"4"},{"id":"D","text":"5"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (22).png","topperAttemptPercent":15.71,"topperAccuracyPercent":72.73,"topperTimeSeconds":30,"topperPValue":11.43},"area":"Logical Reasoning","topic":"Football tournament starting points"},{"id":"ims-dilr-section-1-2026-dilr-q05","sourceNumber":5,"type":"MCQ","prompt":"Which of the following can be the minimum value of the points of any team at the end of Day 4?","answer":"B","options":[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"2"},{"id":"D","text":"3"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (23).png","topperAttemptPercent":15.71,"topperAccuracyPercent":45.45,"topperTimeSeconds":20,"topperPValue":7.14},"area":"Logical Reasoning","topic":"Football tournament starting points"}],"stimulus":"Eight teams A, B, C, D, E, F,G and H participated in an annual national level football tournament. Each team was awarded some starting points (positive integer values) at the beginning of the tournament based on their performances in the last year’s tournament. The starting points of exactly four of the eight teams were equal while the remaining four teams had distinct starting points. No team had fewer starting points than team A.\n\nThe first round of this tournament was to be played over four days with one match everyday. There was no tie in the first round. Points update after each match and carry forward to the next day: if a team with W points defeats a team with L points, then the winner’s new points become W+L (i.e. the winner gains the loser’s pre-match points), and the loser’s new points become L-1. (Points may become 0.) Following points are known:\n\n1. On the first day A and C played against each other. Compared to just before this match, at the end of the match the average points of all eight teams increased by 0.25.\n\n2. On the second day E and F played against each other. Compared to just before this match, at the end of the match the average points of all eight teams again increased by 0.25.\n\n3. On the third day G and H played against each other. After this the average points of all the eight teams increased by 0.5 and became 4.5.\n\n4. On the fourth day B and D played against each other."},{"id":"ims-dilr-section-1-2026-dilr-g06","title":"Spanish game scores","questions":[{"id":"ims-dilr-section-1-2026-dilr-q06","sourceNumber":6,"type":"TITA","prompt":"If Emram's score in Round Uno was equal to Dikram's score in Round Quatre, then what was Fimram's score in round Cinco?","answer":["74"],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (24).png","topperAttemptPercent":91.43,"topperAccuracyPercent":92.19,"topperTimeSeconds":573},"area":"Data Interpretation","topic":"Spanish game scores"},{"id":"ims-dilr-section-1-2026-dilr-q07","sourceNumber":7,"type":"MCQ","prompt":"Referring to the previous question, who scored the least points and in which round?","answer":"C","options":[{"id":"A","text":"Fimram, Round Uno"},{"id":"B","text":"Bikram, Round Tres"},{"id":"C","text":"Dikram, Round Cinco"},{"id":"D","text":"Chakram, Ropund Quatre"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (27).png","topperAttemptPercent":92.86,"topperAccuracyPercent":98.46,"topperTimeSeconds":63,"topperPValue":91.43},"area":"Data Interpretation","topic":"Spanish game scores"},{"id":"ims-dilr-section-1-2026-dilr-q08","sourceNumber":8,"type":"MCQ","prompt":"Referring to the previous question, what is the difference between the highest scorer and the least scorer?","answer":"C","options":[{"id":"A","text":"39"},{"id":"B","text":"43"},{"id":"C","text":"41"},{"id":"D","text":"40"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (28).png","topperAttemptPercent":84.29,"topperAccuracyPercent":88.14,"topperTimeSeconds":94,"topperPValue":74.29},"area":"Data Interpretation","topic":"Spanish game scores"},{"id":"ims-dilr-section-1-2026-dilr-q09","sourceNumber":9,"type":"MCQ","prompt":"Referring to previous question, what is Akram's score in round Quatre?","answer":"C","options":[{"id":"A","text":"60"},{"id":"B","text":"62"},{"id":"C","text":"63"},{"id":"D","text":"65"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (29).png","topperAttemptPercent":90,"topperAccuracyPercent":100,"topperTimeSeconds":46,"topperPValue":90},"area":"Data Interpretation","topic":"Spanish game scores"}],"stimulus":"The table below gives the points scored by six friends Akram, Bikram, Chakram, Dikram, Emram and Fimram in five rounds of a Spanish game. U, D, T, Q and C denote the minimum points obtained by the six students in the five rounds i.e. Rounds Uno, Dos, Tres, Quatre and Cinco (One, Two, Three, Four and Five translated in Spanish) respectively. No one scored less than 50 in any round. The sum of all the points scored by all the friends in all the rounds was 2170.\n\nRounds: Uno | Dos | Tres | Quatre | Cinco\nAkram: U+31 | D | T+13 | Q+4 | C+19\nBikram: U+24 | D+9 | T | Q+7 | C+29\nChakram: U+19 | D+15 | T+8 | Q | C+34\nDikram: U+32 | D+27 | T+36 | Q+26 | C\nEmram: U+26 | D+12 | T+33 | Q+18 | C+21\nFimram: U | D+8 | T+9 | Q | C+24\n\n- Chakram's points in Round Dos was 3 marks less than Emram's marks in Round Quatre.\n\n- Akram's points in Round Uno and Dikram's points in Round Tres were equal.\n\n- Fimram's points in Round Cinco and Chakram's points in Round Dos were equal.","assetIds":["spanish-scores"]},{"id":"ims-dilr-section-1-2026-dilr-g10","title":"Hockey tournament","questions":[{"id":"ims-dilr-section-1-2026-dilr-q10","sourceNumber":10,"type":"MCQ","prompt":"Out of all the matches played in the tournament, results of how many matches can be uniquely determined?","answer":"A","options":[{"id":"A","text":"All"},{"id":"B","text":"All except two"},{"id":"C","text":"All except four"},{"id":"D","text":"All except six"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (31).png","topperAttemptPercent":22.86,"topperAccuracyPercent":87.5,"topperTimeSeconds":341,"topperPValue":20},"area":"Logical Reasoning","topic":"Hockey tournament"},{"id":"ims-dilr-section-1-2026-dilr-q11","sourceNumber":11,"type":"TITA","prompt":"By what margin of goals did India beat Canada?","answer":["4"],"selectionCategory":"C","area":"Logical Reasoning","topic":"Hockey tournament"},{"id":"ims-dilr-section-1-2026-dilr-q12","sourceNumber":12,"type":"MCQ","prompt":"Which match ended in a zero draw?","answer":"A","options":[{"id":"A","text":"Canada vs. Poland"},{"id":"B","text":"Germany vs. Spain"},{"id":"C","text":"India vs. Canada"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (33).png","topperAttemptPercent":24.29,"topperAccuracyPercent":94.12,"topperTimeSeconds":11,"topperPValue":22.86},"area":"Logical Reasoning","topic":"Hockey tournament"},{"id":"ims-dilr-section-1-2026-dilr-q13","sourceNumber":13,"type":"MCQ","prompt":"Which of the following statements is incorrect?","answer":"C","options":[{"id":"A","text":"The two teams that Australia beat with a margin of 6 goals were Spain and India."},{"id":"B","text":"India failed to score a single goal against total 3 teams."},{"id":"C","text":"Australia scored odd number of goals against Canada."},{"id":"D","text":"Australia beat Canada by a margin of 2 goals."}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (35).png","topperAttemptPercent":15.71,"topperAccuracyPercent":81.82,"topperTimeSeconds":18,"topperPValue":12.86},"area":"Logical Reasoning","topic":"Hockey tournament"}],"stimulus":"A hockey tournament was played involving Australia, Germany, Poland, Spain, India and Canada at Hannover, Germany. In the tournament, each team played against every other team exactly once. Each match lasted for 90 minutes and the team that scored more goals than the other team was declared the winner while the team that scored fewer goals than the other team lost the match. If both teams scored equal number of goals, the match was said to be drawn. A team was awarded 2 points for every match won, 1 point for every match drawn and 0 points for every match lost. At the end of the tournament, the points table was as follows:\n\nTeam | Played | Won | Drawn | Lost | Goals scored | Goals conceded\nAustralia | 5 | 4 | 1 | 0 | 23 | 6\nGermany | 5 | 2 | 3 | 0 | 9 | 4\nPoland | 5 | 2 | 1 | 2 | 8 | 9\nSpain | 5 | 2 | 1 | 2 | 7 | 13\nIndia | 5 | 1 | 1 | 3 | 5 | 10\nCanada | 5 | 0 | 1 | 4 | 3 | 13\n\nFurther following information is known:\n\n1. Only one match ended in zero-draw (situation in which both teams fail to score a single goal).\n\n2. Canada failed to score a single goal against Poland and India.\n\n3. Australia scored 2 goals against Germany and beat two other teams by the margin of 6 goals each.\n\n4. Germany scored 3 goals against Poland and 2 goals against Canada. Both Poland and Canada failed to score a single goal against Germany.\n\n5. India failed to score a single goal against Poland and Australia.\n\n6. Poland scored 2 goals against Australia and 5 goals against Spain.\n\n7. Spain scored 2 goals against India and 3 goals against Canada but failed to score a single goal against Australia.","assetIds":["hockey-table"]},{"id":"ims-dilr-section-1-2026-dilr-g14","title":"Citibank campus placements","questions":[{"id":"ims-dilr-section-1-2026-dilr-q14","sourceNumber":14,"type":"MCQ","prompt":"If Amit is the fifth who got an offer from Citibank, then he is from:","answer":"A","options":[{"id":"A","text":"IIMA"},{"id":"B","text":"IIMB"},{"id":"C","text":"IIMC"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (36).png","topperAttemptPercent":98.57,"topperAccuracyPercent":100,"topperTimeSeconds":147,"topperPValue":98.57},"area":"Logical Reasoning","topic":"Citibank campus placements"},{"id":"ims-dilr-section-1-2026-dilr-q15","sourceNumber":15,"type":"MCQ","prompt":"Neha is from:","answer":"B","options":[{"id":"A","text":"IIMA"},{"id":"B","text":"IIMB"},{"id":"C","text":"IIMC"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (37).png","topperAttemptPercent":100,"topperAccuracyPercent":100,"topperTimeSeconds":18,"topperPValue":100},"area":"Logical Reasoning","topic":"Citibank campus placements"},{"id":"ims-dilr-section-1-2026-dilr-q16","sourceNumber":16,"type":"MCQ","prompt":"If Amit is the 5th person who got an offer from Citibank , how many students from Amit's institute got an offer from Citibank?","answer":"B","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (38).png","topperAttemptPercent":100,"topperAccuracyPercent":97.14,"topperTimeSeconds":21,"topperPValue":97.14},"area":"Logical Reasoning","topic":"Citibank campus placements"},{"id":"ims-dilr-section-1-2026-dilr-q17","sourceNumber":17,"type":"MCQ","prompt":"Sandy is from:","answer":"C","options":[{"id":"A","text":"IIMA"},{"id":"B","text":"IIMB"},{"id":"C","text":"IIMC"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (39).png","topperAttemptPercent":100,"topperAccuracyPercent":100,"topperTimeSeconds":10,"topperPValue":100},"area":"Logical Reasoning","topic":"Citibank campus placements"},{"id":"ims-dilr-section-1-2026-dilr-q18","sourceNumber":18,"type":"TITA","prompt":"If Amit is the 5th student who got an offer, the institutes of how many of the 5 students can be uniquely determined?","answer":["5"],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (40).png","topperAttemptPercent":100},"area":"Logical Reasoning","topic":"Citibank campus placements"}],"stimulus":"The most prized company to come for campus placements this year at IIMA, IIMB and IIMC was Citibank. With a whopping pay package of $225000 per annum, it selected five students from the three IIMs. Rohit who was not from IIMC was given an offer. Two IIMA students got the offers while only one IIMC student got the offer. Sandy and Neha both were not from IIMA while Neha and Ashita were from the same institute."},{"id":"ims-dilr-section-1-2026-dilr-g19","title":"Coloured boxes and balls","questions":[{"id":"ims-dilr-section-1-2026-dilr-q19","sourceNumber":19,"type":"MCQ","prompt":"If the red ball is in the box to the left of the box containing the black ball, which coloured box contains the pair of trousers?","answer":"B","options":[{"id":"A","text":"Yellow"},{"id":"B","text":"Pink"},{"id":"C","text":"Blue"},{"id":"D","text":"Green"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (41).png","topperAttemptPercent":98.57,"topperAccuracyPercent":100,"topperTimeSeconds":396,"topperPValue":98.57},"area":"Logical Reasoning","topic":"Coloured boxes and balls"},{"id":"ims-dilr-section-1-2026-dilr-q20","sourceNumber":20,"type":"MCQ","prompt":"If the pink ball is to the immediate right of the black ball, in which coloured box is the pair of trousers?","answer":"A","options":[{"id":"A","text":"Red"},{"id":"B","text":"Green"},{"id":"C","text":"Blue"},{"id":"D","text":"Black"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (42).png","topperAttemptPercent":97.14,"topperAccuracyPercent":98.53,"topperTimeSeconds":74,"topperPValue":95.71},"area":"Logical Reasoning","topic":"Coloured boxes and balls"},{"id":"ims-dilr-section-1-2026-dilr-q21","sourceNumber":21,"type":"MCQ","prompt":"If the jacket is in the blue coloured box, what coloured ball is in the box containing the handkerchief?","answer":"D","options":[{"id":"A","text":"Yellow"},{"id":"B","text":"Green"},{"id":"C","text":"Pink"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (43).png","topperAttemptPercent":80,"topperAccuracyPercent":92.86,"topperTimeSeconds":121,"topperPValue":74.29},"area":"Logical Reasoning","topic":"Coloured boxes and balls"},{"id":"ims-dilr-section-1-2026-dilr-q22","sourceNumber":22,"type":"MCQ","prompt":"The cap is in the ______ coloured box","answer":"D","options":[{"id":"A","text":"Yellow"},{"id":"B","text":"Green"},{"id":"C","text":"Blue"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (44).png","topperAttemptPercent":94.29,"topperAccuracyPercent":92.42,"topperTimeSeconds":53,"topperPValue":87.14},"area":"Logical Reasoning","topic":"Coloured boxes and balls"}],"stimulus":"Six boxes coloured red, green, yellow, pink, blue and black are placed in a row from left to right in that order. Each box contains a ball and one of the following things: a handkerchief, a shirt, a pair of trousers, a T-Shirt, a jacket and a cap. There is exactly one ball of each of the six colours: red, green, yellow, pink, blue and black. For any colour, the ball bearing that colour is not in the box bearing the same colour and also, not in either box adjacent to the box bearing the same colour. The green ball is not in the black box. The blue and green balls are equidistant from the ends. The shirt is in the box that contains the red ball. The trousers are in the box that contains the black ball. The T-Shirt is not in the box containing the green ball or in the box containing the yellow ball. The cap is in the box containing the blue ball."}]}],"assets":{"spanish-scores":{"alt":"Original Spanish game score table; the values are also transcribed above.","data":"data:image/png;base64,"},"hockey-table":{"alt":"Original hockey tournament table; the values are also transcribed above.","data":"data:image/png;base64,"}}},{"schemaVersion":1,"testType":"full","id":"ims-simcat-2-2026","revision":1,"title":"SimCAT 2 · 2026","description":"68 questions across VARC, DILR and QA. Transcribed from your IMS images, with supplied question benchmarks.","sections":[{"code":"VARC","groups":[{"id":"ims-simcat-2-2026-varc-g01","title":"RC · Cetacean evolution","questions":[{"id":"ims-simcat-2-2026-varc-q01","sourceNumber":1,"type":"MCQ","prompt":"“One striking pattern was the loss of entire genes.” This observation is primarily used to support the idea that:","answer":"C","options":[{"id":"A","text":"Fossils were inadequate in reconstructing the evolutionary history of whales."},{"id":"B","text":"Life in aquatic environments imposed harsher constraints than life on land."},{"id":"C","text":"Evolutionary adaptation involved the selective elimination of biological functions."},{"id":"D","text":"Most major anatomical changes in cetaceans were not driven by natural selection."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (45).png","topperAttemptPercent":91.6,"topperAccuracyPercent":92.36,"topperTimeSeconds":303,"topperPValue":84.6},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q02","sourceNumber":2,"type":"MCQ","prompt":"All of the following claims are consistent with the passage EXCEPT:","answer":"D","options":[{"id":"A","text":"Some evolutionary changes in cetaceans improved survival by reducing physiological risks."},{"id":"B","text":"Genetic evidence helped explain adaptive changes more accurately than skeletal remains."},{"id":"C","text":"Cetaceans fine-tuned existing biological systems rather than change them completely."},{"id":"D","text":"Gene loss in cetaceans largely reflects genetic decay caused by the reduced usefulness."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (46).png","topperAttemptPercent":84.4,"topperAccuracyPercent":36.02,"topperTimeSeconds":92,"topperPValue":30.4},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q03","sourceNumber":3,"type":"MCQ","prompt":"Which one of the following assumptions is central to the passage’s argument about genetic and physiological changes?","answer":"A","options":[{"id":"A","text":"Organisms that returned to water retained biological systems shaped for land life."},{"id":"B","text":"Major environmental transitions typically favour the suppression of redundant traits."},{"id":"C","text":"Genetic evidence can reveal adaptive processes not visible through physiological change."},{"id":"D","text":"Challenges of deep sea life assert stronger evolutionary pressures than surface living."}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (47).png","topperAttemptPercent":82.2,"topperAccuracyPercent":16.55,"topperTimeSeconds":64,"topperPValue":13.6},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q04","sourceNumber":4,"type":"MCQ","prompt":"“For decades, their bizarre body plans perplexed palaeontologists, who speculated that whales might have arisen from creatures as varied as marine reptiles, seals, marsupials, or even extinct wolf-like carnivores” Which of the following can be inferred from the statement?","answer":"B","options":[{"id":"A","text":"Superiority of genetics over palaeontology in studying evolutionary change."},{"id":"B","text":"External anatomy does not fully reflect evolutionary relationships."},{"id":"C","text":"The diversity of marine and semi-aquatic animals that coexisted with cetaceans."},{"id":"D","text":"Non-reptilian origins of fully aquatic animals."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (48).png","topperAttemptPercent":87.6,"topperAccuracyPercent":88.36,"topperTimeSeconds":65,"topperPValue":77.4},"area":"Reading Comprehension","topic":"RC"}],"stimulus":"Around 400 million years ago, the ancestor of all four-limbed creatures took its first steps onto dry land. Fast-forward about 350 million years, and a descendant of these early landlubbers did an about-face: It waded back into the water. With time, the back-to-the-sea creatures would give rise to animals vastly different from their land-trotting kin. They became the whales, dolphins, and porpoises that glide through the oceans today.\n\nGoing back to an aquatic lifestyle was a drastic move that would change these animals inside and out, over roughly 10 million years—an evolutionary eyeblink. Members of this group, now called cetaceans, dropped their hind limbs for powerful flukes and lost nearly all their hair. For decades, their bizarre body plans perplexed palaeontologists, who speculated that whales might have arisen from creatures as varied as marine reptiles, seals, marsupials, or even extinct wolf-like carnivores.\n\nIn the late 1990s, genetic data resolved the mystery, confirming that whales belonged to the same evolutionary line as cows, pigs, and camels. Fossils from modern-day India and Pakistan later fleshed out this family tree, identifying the closest ancient relatives of cetaceans as small, wading, deer-like mammals. Yet external anatomy was only part of the story. To survive in the sea, cetaceans also had to modify their blood, lungs, skin, and metabolism—changes that fossils alone could not easily reveal.\n\nWith the increasing availability of cetacean genomes, geneticists began identifying the molecular changes that accompanied the transition back to water. One striking pattern was the loss of entire genes. In the vast book of genetic letters that make up a genome, defunct genes stand out like garbled sentences: They no longer encode functional proteins. Researchers have identified dozens of genes that became nonfunctional when cetaceans adapted to aquatic life.\n\nSome losses were intuitive. Cetaceans no longer possess a gene involved in making saliva, an unnecessary function when the mouth is already full of water. They also lost several genes related to melatonin production and sleep regulation. Early whales likely discovered quickly that shutting down their brains for hours was incompatible with the need to surface to breathe. Modern cetaceans sleep one brain hemisphere at a time, keeping the other alert.\n\nOther genetic changes reflect the demands of deep diving. Long dives can cause nitrogen bubbles to form in the blood, increasing the risk of clots. Two genes involved in initiating blood clotting are no longer functional in cetaceans, reducing this danger while leaving the rest of the clotting system intact. Another lost gene encoded an enzyme that repaired DNA inaccurately. During repeated dives, oxygen flooding back into the bloodstream produces reactive molecules that damage DNA; abandoning a sloppy repair enzyme may have improved long-term cellular stability.\n\nNot all adaptations involved loss. Cetaceans gained changes in genes such as myoglobin, allowing their muscles to store large quantities of oxygen. Their lungs became highly elastic, enabling rapid exchange of air at the surface. At the same time, genes for smell and taste were greatly reduced, reflecting the limited usefulness of these senses underwater."},{"id":"ims-simcat-2-2026-varc-g05","title":"RC · Scientific cultures","questions":[{"id":"ims-simcat-2-2026-varc-q05","sourceNumber":5,"type":"MCQ","prompt":"Which one of the following best summarises the central argument of the passage?","answer":"C","options":[{"id":"A","text":"Differences among scientific disciplines arise primarily from the kinds of evidence they employ, leading to distinct standards of proof and collaboration."},{"id":"B","text":"Scientific progress is hindered when disciplines misunderstand one another's methods, making interdisciplinary research a social problem and a technical one."},{"id":"C","text":"The practices, norms, and values of scientific disciplines evolve in response to their subject matter, and investigative constraints require unique ways of generating knowledge."},{"id":"D","text":"While scientific disciplines vary in language, tolerance for error, and modes of collaboration, they remain united by a common commitment to empirical rigor."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (49).png","topperAttemptPercent":65.8,"topperAccuracyPercent":54.41,"topperTimeSeconds":211,"topperPValue":35.8},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q06","sourceNumber":6,"type":"MCQ","prompt":"The difference between mathematical proof and experimental validation (2nd Paragraph) is primarily used to illustrate which one of the following points?","answer":"D","options":[{"id":"A","text":"Mathematics seeks complete certainty, while experimental science works with tentative results."},{"id":"B","text":"Experimental sciences make up for weaker logic by relying on repeated trials and statistics."},{"id":"C","text":"Mathematical thinking cannot be combined with empirical research."},{"id":"D","text":"Different fields use different ways of justifying knowledge, shaped by how they produce and test ideas."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (50).png","topperAttemptPercent":73.6,"topperAccuracyPercent":92.66,"topperTimeSeconds":47,"topperPValue":68.2},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q07","sourceNumber":7,"type":"MCQ","prompt":"All of the following statements can be inferred from the passage EXCEPT that:","answer":"D","options":[{"id":"A","text":"Differences between scientific fields involve not only methods, but also norms about proof, teamwork, and attitudes toward mistakes."},{"id":"B","text":"Interdisciplinary collaboration means learning to understand different ways of thinking, not just exchanging information."},{"id":"C","text":"Fields focused on abstract reasoning are more likely to stress individual achievement than those based on large experiments."},{"id":"D","text":"The lack of one universal scientific method reduces the overall credibility and reliability of science."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (51).png","topperAttemptPercent":66.8,"topperAccuracyPercent":95.81,"topperTimeSeconds":37,"topperPValue":64},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q08","sourceNumber":8,"type":"MCQ","prompt":"Which one of the following assumptions is most critical to the author's argument that “collaboration across fields is not just a technical challenge but a social one ...”?","answer":"B","options":[{"id":"A","text":"Scientists from different fields often disagree about basic facts and experimental findings."},{"id":"B","text":"Successful interdisciplinary work requires addressing differences in thinking, reasoning, and communication."},{"id":"C","text":"Social differences between disciplines are harder to overcome than technical or methodological problems."},{"id":"D","text":"Interdisciplinary research cannot succeed unless one field sets the common method."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (52).png","topperAttemptPercent":67.4,"topperTimeSeconds":45,"topperPValue":56.8,"topperAccuracyPercent":84.27},"area":"Reading Comprehension","topic":"RC"}],"stimulus":"Walk through the corridors of different scientific departments and you quickly sense that “science” is not a single culture but a federation of distinct ways of knowing. The physicist hunched over equations, the biologist pipetting at a bench, and the economist wrestling with datasets may all claim allegiance to evidence and rigor, yet what counts as a good question, a convincing answer, or even an elegant solution varies sharply among them. These differences are not superficial; they are cultural habits, shaped over time by the objects each discipline studies and the tools it relies upon.\n\nConsider how disciplines define proof. In mathematics, a result is not accepted because it works most of the time or because it matches observation, but because it follows inevitably from axioms through logical argument. A single counterexample is fatal, no matter how persuasive the intuition behind the claim. By contrast, in the experimental sciences, certainty is probabilistic. A biological finding gains credibility through repeated trials, statistical significance, and independent replication, even though absolute certainty remains elusive. What matters is not deductive inevitability, but robustness across conditions.\n\nThese epistemic styles shape everyday scientific behavior. In some fields, collaboration is the norm, driven by expensive equipment, large datasets, or complex experiments that exceed individual capacity. Authorship lists grow long, and credit is distributed collectively. In others, particularly those centered on abstract reasoning, solitary work remains common, and intellectual ownership is more tightly guarded. Neither approach is inherently superior; each reflects a different understanding of how knowledge is best produced.\n\nDisciplinary cultures also influence attitudes toward failure. In engineering and applied sciences, failed prototypes are often treated as informative steps toward improvement. Error is productive, a signal that guides redesign. In contrast, fields that prize formal elegance or theoretical coherence may view error less forgivingly, since a single flaw can undermine an entire framework. As a result, researchers internalize different tolerances for risk, speculation, and intellectual exposure.\n\nEven the language scientists use reveals cultural divides. Some disciplines favor dense formalism, believing that precision requires abstraction and symbolic expression. Others privilege narrative explanation, metaphors, and visual models to make sense of complex systems. These preferences affect how research is communicated to outsiders and how easily ideas travel across disciplinary boundaries. Misunderstandings often arise not from disagreement about facts, but from incompatible styles of reasoning and expression.\n\nWhat unites these diverse cultures is not a uniform method but a shared commitment to disciplined inquiry. Each field develops norms that regulate skepticism, trust, and authority in ways suited to its subject matter. Problems arise when one disciplinary style is treated as the gold standard for all knowledge. Demands that every science look like physics, or every argument resemble a mathematical proof, ignore the fact that different domains of reality require different epistemic tools.\n\nIn an era of interdisciplinary research, these cultural differences matter more than ever. Collaboration across fields is not just a technical challenge but a social one, requiring translation between distinct ways of knowing. Appreciating disciplinary cultures does not weaken science; it strengthens it, reminding us that progress depends not on a single scientific voice, but on a productive conversation among many."},{"id":"ims-simcat-2-2026-varc-g09","title":"RC · AI and humor","questions":[{"id":"ims-simcat-2-2026-varc-q09","sourceNumber":9,"type":"MCQ","prompt":"According to the passage, AI-generated humor remains fundamentally limited for all the following reasons EXCEPT:","answer":"C","options":[{"id":"A","text":"AI lacks emotional experience and cannot react internally to humor."},{"id":"B","text":"AI struggles to deploy humor intentionally within social contexts."},{"id":"C","text":"AI finds it difficult to create the typical language of jokes and puns."},{"id":"D","text":"AI’s humor is shaped by patterns in data rather than by social aims."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (53).png","topperAccuracyPercent":92.68,"topperTimeSeconds":224,"topperPValue":83.6,"topperAttemptPercent":90.2},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q10","sourceNumber":10,"type":"MCQ","prompt":"The third paragraph of the passage is primarily used to support the claim that:","answer":"D","options":[{"id":"A","text":"Philosophical accounts converge on ambiguity as a defining feature of jokes."},{"id":"B","text":"Linguistic jokes rely on cultural knowledge over computational abilities."},{"id":"C","text":"The effectiveness of humor depends more on the flexible meaning of words than on the social context of the joke."},{"id":"D","text":"Humor relies on semantic surprise rather than on commonly understood meaning."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (54).png","topperPValue":66.8,"topperAttemptPercent":86.2,"topperAccuracyPercent":77.49,"topperTimeSeconds":79},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q11","sourceNumber":11,"type":"MCQ","prompt":"“Despite these advances, most scientists believe A.I’s humor lacks the deeper intentionality that characterizes human wit.” Which one of the following best describes the use of the word “intentionality”?","answer":"C","options":[{"id":"A","text":"The ability to generate jokes that do not conform to established linguistic structures."},{"id":"B","text":"The consistency with which humorous outputs produce amusement in an audience."},{"id":"C","text":"The skill to use humor to convey social meaning beyond the literal content of a joke."},{"id":"D","text":"The subjective awareness of being humorous while producing a joke."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (55).png","topperAttemptPercent":85.8,"topperAccuracyPercent":76.69,"topperTimeSeconds":67,"topperPValue":65.8},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q12","sourceNumber":12,"type":"MCQ","prompt":"Assuming that the authorship of a joke is unknown, which of the following, according to the passage, would most reliably indicate that the joke is human-generated rather than machine-generated?","answer":"B","options":[{"id":"A","text":"The joke displays ambiguity that requires reinterpretation to be understood."},{"id":"B","text":"The joke is used to manage social situations rather than merely to be funny."},{"id":"C","text":"The joke elicits laughter from audiences across different contexts."},{"id":"D","text":"The joke deviates from conventional linguistic patterns of humor."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (56).png","topperAttemptPercent":84.4,"topperAccuracyPercent":81.75,"topperTimeSeconds":61,"topperPValue":69},"area":"Reading Comprehension","topic":"RC"}],"stimulus":"Humor has long been considered one of the most complex forms of human expression, a blend of language, culture and social intuition that seemed far beyond the capabilities of machines. Until recently, jokes were thought to require “all the thinking ability of a typical human” to be recognized or produced. Yet advances in large language models (LLMs) have challenged this assumption, prompting researchers to ask whether artificial intelligence can truly grasp—or convincingly imitate—the nuances of human humor.\n\nModern LLMs can produce wordplay, puns and structured jokes with surprising fluency. Some researchers argue that, at least at the textual level, humor has proved easier for A.I. to generate than tasks like self-driving. But crafting a clever punchline is not the same as wielding humor in the context-rich way humans do. Humor operates within social norms: it signals group belonging, eases embarrassment, masks criticism or opens pathways for emotional connection. These subtle functions demand an understanding of intention, boundary-testing and interpersonal cues—areas where today’s A.I. tools still falter.\n\nPhilosophers and linguists have long tried to explain why people laugh. From early theories that framed humor as an assertion of superiority to modern views highlighting ambiguity and incongruity, researchers agree that successful jokes often hinge on a delicate mental shift. A pun such as “Two fish are in a tank. One says, ‘You man the guns, I'll drive;’” works because the listener must rapidly reinterpret the word “tank,” moving from the image of an aquarium to that of a military vehicle. This quick flicker of surprise and resolution is central to many jokes—and difficult for algorithms to master consistently.\n\nNonetheless, AI systems are learning faster than expected. In recent experiments, language models trained on satirical headlines produced content that readers rated as nearly indistinguishable from human-generated humor. Other tools combine structured joke-writing algorithms with LLMs to create full setups and punchlines based on a simple prompt. These systems can generate dozens of responses, some remarkably sharp. Yet human curation remains essential: editors or comedians still hand-select the genuinely funny lines from a sea of mediocre attempts.\n\nDespite these advances, most scientists believe A.I.’s humor lacks the deeper intentionality that characterizes human wit. Machines do not use jokes to navigate awkwardness, test social waters or express emotional subtext. They generate patterns—not purposes. This limitation also exposes risks. When asked to “make images funnier,” some A.I. tools resorted to stereotypical portrayals, overrepresenting certain body types or diminishing minority characters. Such biases highlight the social blind spots that emerge when humor is treated purely as data.\n\nThere is also evidence that audiences react differently when they know a machine wrote the joke: people tend to find it less funny, suggesting that humor is intertwined with perceptions of human intention. Researchers argue that genuine humor arises from emotional reactions—not merely from assembling clever words. A.I. can produce jokes, but it cannot feel amusement, discomfort, embarrassment or insight. As one expert puts it, the uniquely human step is reacting emotionally to humor, even when a joke is crude, unsettling or revealing. Machines, for now, can imitate humor’s structure—but not its soul."},{"id":"ims-simcat-2-2026-varc-g13","title":"Summary · Hope","questions":[{"id":"ims-simcat-2-2026-varc-q13","sourceNumber":13,"type":"MCQ","prompt":"The passage given below is followed by four summaries. Choose the option that best captures the essence of the passage.\n\nHope is often celebrated as a universal virtue, yet it can also become a subtle source of disappointment and distress. When people cling too tightly to hopes about the future, they risk tying their peace of mind to outcomes beyond their control. Many Eastern traditions have long suggested that letting go of excessive hope can lead to greater calm and clarity in the present. Some Western thinkers have echoed this view, noting that fewer expectations can bring unexpected relief. In contrast, modern culture often treats hope as a moral duty, rooted in religious ideas of salvation and Enlightenment faith in progress. This approach encourages people to endure present suffering for imagined future rewards. Yet true courage may lie in facing reality without illusion. By releasing the pressure to constantly hope for better outcomes, individuals can learn to accept uncertainty, engage more honestly with life, and discover a quieter, more stable form of contentment grounded in awareness rather than anticipation.","answer":"C","options":[{"id":"A","text":"Eastern and Western traditions converge in rejecting excessive hope as harmful, in contrast to modern culture making hope a moral obligation."},{"id":"B","text":"Modern society's valorisation of hope encourages people to tolerate present suffering in anticipation of future rewards, while most traditions reject hope as a universal virtue."},{"id":"C","text":"Excessive attachment to hope can undermine present peace, while letting it go it may bring calm, acceptance, and a more stable form of contentment."},{"id":"D","text":"Excessive attachment to hope is rejected by both eastern and western traditions, encouraging individuals to accept uncertainty for a quieter, more honest life."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (57).png","topperAttemptPercent":83},"area":"Verbal Reasoning","topic":"Summary"}]},{"id":"ims-simcat-2-2026-varc-g14","title":"Paragraph ordering · Impact investing","questions":[{"id":"ims-simcat-2-2026-varc-q14","sourceNumber":14,"type":"TITA","prompt":"The four sentences (labelled 1, 2, 3, and 4) given below, when properly sequenced, would yield a coherent paragraph. Decide on the proper sequencing of the order of the sentences and key in the sequence of the four numbers as your answer.\n\n1. In a revised edition of Impact: Reshaping Capitalism to Drive Real Change, Sir Ronald Cohen reflects on how investment practices are being reshaped by social and environmental concerns.\n\n2. Based on his long experience in venture capital, he observes that financial decision-making is gradually incorporating measures of public benefit alongside profit.\n\n3. He identifies innovation, outcome measurement, and cooperation among firms, governments, and social enterprises as central to this transformation.\n\n4. At the same time, Cohen acknowledges that meaningful alignment between commercial returns and social impact remains limited, suggesting that the emerging model is still incomplete and evolving.","answer":["1324"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (58).png","topperAttemptPercent":90.2,"topperAccuracyPercent":28.82,"topperTimeSeconds":98},"area":"Verbal Reasoning","topic":"Paragraph ordering"}]},{"id":"ims-simcat-2-2026-varc-g15","title":"Sentence placement · Political movements","questions":[{"id":"ims-simcat-2-2026-varc-q15","sourceNumber":15,"type":"MCQ","prompt":"The given sentence is missing in the paragraph below. Decide where it best fits among the options 1, 2,3, or 4 indicated in the paragraph.\n\nSentence: This strategy would unite victims of globalization with nostalgic supporters of past conservative leaders.\n\nParagraph: Imagine a hidden blueprint left behind by twentieth-century fascists for their political heirs. It would begin by copying the language of the left, attacking crony capitalism, financial elites, and corrupt institutions.___(1)___. It would criticize the political system as a closed “uniparty” while repeating extreme neoliberal slogans and blaming public workers for economic decline.___(2)___. It would then portray moderate politicians as dangerous radicals and promise a return to a mythical golden age. Through emotional speeches and constant repetition, it would turn resentment into loyalty and doubt into anger.___(3)___. Above all, it would rely on fears about identity and purity, depicting outsiders as threats and social change as contamination. By mixing familiar grievances with exaggerated dangers, such a movement could disguise authoritarian control as popular rebellion and present exclusion and domination as national renewal.___(4)___.","answer":"D","options":[{"id":"A","text":"Option 2"},{"id":"B","text":"Option 4"},{"id":"C","text":"Option 1"},{"id":"D","text":"Option 3"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (59).png","topperAttemptPercent":74.6,"topperAccuracyPercent":31.64,"topperTimeSeconds":101},"area":"Verbal Reasoning","topic":"Sentence placement"}]},{"id":"ims-simcat-2-2026-varc-g16","title":"Odd sentence · Aesthetics","questions":[{"id":"ims-simcat-2-2026-varc-q16","sourceNumber":16,"type":"TITA","prompt":"Five jumbled sentences (labelled 1, 2, 3, 4, and 5), related to a topic, are given below. Four of them can be put together to form a coherent paragraph. Identify the odd sentence out and key in the number of that sentence as your answer.\n\n1. The study of aesthetics, which examines these experiences across cultures and disciplines, emerged as a distinct field in the eighteenth century, though its intellectual roots extend back to ancient thought.\n\n2. Aesthetics is closely related to the philosophy of art, and the two terms are often used interchangeably since both involve the philosophical study of aesthetic phenomena.\n\n3. Some thinkers define art by its aesthetic qualities, while others view it as a category shaped by social and cultural contexts.\n\n4. Artworks are human creations that appear in many forms, including painting, music, dance, architecture, and literature.\n\n5. Interpretation and criticism seek to uncover what artworks represent, the emotions they express, and the intentions behind them.","answer":["1"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (60).png","topperAttemptPercent":89},"area":"Verbal Reasoning","topic":"Odd sentence"}]},{"id":"ims-simcat-2-2026-varc-g17","title":"Summary · Kochi-Muziris Biennale","questions":[{"id":"ims-simcat-2-2026-varc-q17","sourceNumber":17,"type":"MCQ","prompt":"The passage given below is followed by four summaries. Choose the option that best captures the essence of the passage.\n\nThe Kochi-Muziris Biennale has steadily evolved into a vibrant platform that brings together multiple artistic sensibilities through innovative and diverse mediums. Moving beyond traditional forms, it embraces installations, digital art, performance, soundscapes, and community-based projects, creating a space where varied voices can coexist and interact. Artists from different cultural, social, and political backgrounds use the Biennale to explore themes of identity, memory, migration, and environment. This expansion reflects a commitment to inclusivity, allowing emerging and established creators to experiment freely. By blending local histories with global perspectives, the Biennale transforms Kochi into a living gallery that extends beyond formal exhibition spaces. Its openness to unconventional materials and hybrid practices challenges audiences to rethink what art can be. In doing so, the Kochi-Muziris Biennale not only showcases aesthetic innovation but also encourages dialogue, reflection, and participation, reaffirming its role as a dynamic meeting point of ideas, experiences, and creative expressions.","answer":"B","options":[{"id":"A","text":"The Biennale’s growing emphasis on unconventional mediums and global participation has helped position Kochi as an important centre of contemporary art."},{"id":"B","text":"The Kochi-Muziris Biennale expands artistic practice beyond traditional formats to create an inclusive, interactive space that blends local and global perspectives."},{"id":"C","text":"The Biennale rejects the traditional formats to use diverse art forms to address social themes such as identity, migration, and the environment in a public setting."},{"id":"D","text":"The Kochi-Muziris Biennale has transformed the traditional Kochi into a living gallery that blends local histories and global perspectives on nature of art itself."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (61).png","topperAttemptPercent":66.2},"area":"Verbal Reasoning","topic":"Summary"}]},{"id":"ims-simcat-2-2026-varc-g18","title":"RC · LUCA","questions":[{"id":"ims-simcat-2-2026-varc-q18","sourceNumber":18,"type":"MCQ","prompt":"According to the passage, LUCA seemed “almost ‘alien” in all of the following respects EXCEPT:","answer":"C","options":[{"id":"A","text":"Its reliance on anaerobic and autotrophic metabolism rather than oxygen-based respiration."},{"id":"B","text":"Its dependence on naturally occurring geochemical reactions to compensate for missing cellular functions."},{"id":"C","text":"Its biological machinery was itself sufficient to sustain life without reliance on environmental chemistry."},{"id":"D","text":"Its habitation of deep, iron- and sulfur-rich hydrothermal vent environments, unlike most present-day life."}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (62).png","topperAttemptPercent":73,"topperAccuracyPercent":90.14,"topperTimeSeconds":163,"topperPValue":65.8},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q19","sourceNumber":19,"type":"MCQ","prompt":"What role does the discussion of earlier “universal gene” approaches play in the passage?","answer":"A","options":[{"id":"A","text":"It created the background for a more restrictive strategy to identify LUCA’s genes."},{"id":"B","text":"It provides historical background to the expansion of genetic databases over time."},{"id":"C","text":"It demonstrates that most organisms can be reliably traced back to LUCA."},{"id":"D","text":"It highlights the difficulty of studying ancient microbes due to gene loss over time."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (63).png","topperAttemptPercent":66,"topperAccuracyPercent":69.7,"topperTimeSeconds":60,"topperPValue":46},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q20","sourceNumber":20,"type":"MCQ","prompt":"Martin's claim that the 355 genes “almost certainly belonged to LUCA\" depends most on which assumption?","answer":"D","options":[{"id":"A","text":"Early life forms necessarily possessed fewer genes than organisms that evolved later."},{"id":"B","text":"Genes involved in basic metabolism tend to persist unchanged across long evolutionary periods."},{"id":"C","text":"Chemical conditions at hydrothermal vents compensated for biological limitations in early cells."},{"id":"D","text":"Gene patterns that remain stable across major lineages are more likely inherited than acquired in later exchange."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (64).png","topperAttemptPercent":63.8,"topperAccuracyPercent":75.86,"topperTimeSeconds":49,"topperPValue":48.4},"area":"Reading Comprehension","topic":"RC"},{"id":"ims-simcat-2-2026-varc-q21","sourceNumber":21,"type":"MCQ","prompt":"Which of the following inferences about the origin of life is most consistent with the passage?","answer":"B","options":[{"id":"A","text":"Life as we know it owes its existence entirely to geochemical processes rather than biological ones."},{"id":"B","text":"Early life represents a transitional stage in which chemical reactions compensated for biological processes."},{"id":"C","text":"Biological self-sufficiency emerged before chemical processes played a significant role in sustaining life."},{"id":"D","text":"Modern life continues to rely on the same geochemical mechanisms that sustained the earliest organisms."}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (65).png","topperAccuracyPercent":92.56,"topperTimeSeconds":53,"topperPValue":57.2,"topperAttemptPercent":61.8},"area":"Reading Comprehension","topic":"RC"}],"stimulus":"Around 4 billion years ago there lived a microbe called LUCA — the Last Universal Common Ancestor. Evidence suggests it may have occupied deep, iron- and sulfur-rich hydrothermal vents, leading a lifestyle that would seem almost ‘alien’ today. Anaerobic and autotrophic, it did not breathe oxygen and produced its own food from the dark, metal-laden environment around it. Its metabolism relied on hydrogen, carbon dioxide and nitrogen, converting them into compounds such as ammonia. Most remarkable of all, this modest microbe stands at the root of the lineage that includes every organism on Earth.\n\nFor decades, researchers have tried to determine which genes LUCA actually possessed and what those genes reveal about how it lived. Early studies focused on universal genes—those found in all modern genomes—on the assumption that any gene shared by all organisms must have originated in LUCA. This strategy identified roughly 30 genes, but they offered too little information to paint a clear picture of LUCA's environment or metabolism. Another approach widened the search to include any gene present in at least one species of archaea and one species of bacteria. This produced more than 11,000 candidate genes. Yet such a massive set seemed implausible; LUCA could not have possessed more abilities than any modern cell.\n\nBill Martin and his team saw the problem: a process known as lateral gene transfer (LGT) was obscuring LUCA's true genetic signature. LGT allows genes to jump between species—and even between domains—through mechanisms such as viruses or homologous recombination when cells experience stress. Over billions of years, these transfers have shuffled genes extensively, making many of the 11,000 shared genes poor indicators of ancient ancestry. Genes found in both archaea and bacteria today may have spread horizontally rather than having been inherited from LUCA.\n\nRecognizing this, Martin's group adopted a different strategy. Instead of looking for genes that were merely widespread, they searched for “ancient” genes—those whose evolutionary lineages are unusually long and show little evidence of having been moved around by LGT. They reasoned that such genes were more likely to have descended directly from LUCA. To qualify, a gene had to meet two conditions: it could not show signs of lateral transfer, and it had to appear in at least two major groups of archaea and two major groups of bacteria.\n\n“While we were going through the data, we had goosebumps because it was all pointing in one very specific direction,” Martin recalls.\n\nIn the end, the team identified just 355 genes that met their stringent criteria. They argue that these genes almost certainly belonged to LUCA and provide valuable insights into its lifestyle. Although 355 genes would be far too few to support life as we know it today, Martin notes that LUCA likely depended heavily on its geochemical environment, using naturally occurring reactions in hydrothermal vents to supplement missing cellular functions. Critics have observed that key components for processes like nucleotide and amino-acid synthesis are absent from the set. “We didn't even have a complete ribosome,” Martin admits. But this, he argues, is precisely the point: LUCA may have been far more chemically intertwined with its environment than any modern organism, representing an early stage in the transition from geochemistry to biology."},{"id":"ims-simcat-2-2026-varc-g22","title":"Paragraph ordering · Population","questions":[{"id":"ims-simcat-2-2026-varc-q22","sourceNumber":22,"type":"TITA","prompt":"The four sentences (labelled 1, 2, 3, and 4) given below, when properly sequenced, would yield a coherent paragraph. Decide on the proper sequencing of the order of the sentences and key in the sequence of the four numbers as your answer.\n\n1. One outcome of the transition can be seen in ageing societies, particularly in Central and Eastern Europe, where economic development has lagged behind demographic change.\n\n2. In many parts of the world, birth rates have already fallen below replacement levels, making a global population peak increasingly likely within this century.\n\n3. Population pressures are commonly associated with fears of unchecked growth, yet a quieter shift toward low fertility may prove more consequential in the long run.\n\n4. Underlying these patterns are broader shifts in social behavior, including delayed marriage, smaller families, and declining interest in traditional family structures, with lasting economic and social effects.","answer":["3241"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (66).png","topperAttemptPercent":84,"topperAccuracyPercent":37.14,"topperTimeSeconds":108},"area":"Verbal Reasoning","topic":"Paragraph ordering"}]},{"id":"ims-simcat-2-2026-varc-g23","title":"Sentence placement · International cooperation","questions":[{"id":"ims-simcat-2-2026-varc-q23","sourceNumber":23,"type":"MCQ","prompt":"The given sentence is missing in the paragraph below. Decide where it best fits among the options 1, 2,3, or 4 indicated in the paragraph.\n\nSentence: The sense of shared responsibility fades.\n\nParagraph: There is growing evidence that the world is moving toward a more unstable and dangerous phase. International cooperation is weakening, and trust between nations is steadily eroding.___(1)___. As multilateral institutions lose influence, countries increasingly rely on military strength for security. Many governments are expanding their arsenals and strengthening defense alliances.___(2)___. These actions are often presented as precautionary measures. Yet they also encourage rivals to respond in kind. Fear produces preparation, and preparation produces further fear. This cycle creates a self-reinforcing pattern of suspicion and escalation. Small incidents now carry greater risks than before.___(3)___. Diplomatic missteps can quickly turn into serious confrontations. In such an environment, restraint becomes harder to maintain.___ {4)__. What emerges instead is a fragile world shaped by rivalry, rapid reactions, and constant anxiety.","answer":"C","options":[{"id":"A","text":"Option 2"},{"id":"B","text":"Option 3"},{"id":"C","text":"Option 1"},{"id":"D","text":"Option 4"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (67).png","topperAttemptPercent":79.2,"topperAccuracyPercent":41.67,"topperTimeSeconds":77,"topperPValue":33},"area":"Verbal Reasoning","topic":"Sentence placement"}]},{"id":"ims-simcat-2-2026-varc-g24","title":"Odd sentence · Illusions","questions":[{"id":"ims-simcat-2-2026-varc-q24","sourceNumber":24,"type":"TITA","prompt":"Five jumbled sentences (labelled 1, 2, 3, 4, and 5), related to a topic, are given below. Four of them can be put together to form a coherent paragraph. Identify the odd sentence out and key in the number of that sentence as your answer.\n\n1. Although illusions alter reality, they are usually experienced in similar ways by most people, with visual illusions being the most common because vision often dominates the other senses.\n\n2. Unlike hallucinations, which occur without any external stimulus, illusions involve the misinterpretation of real sensations, showing how perception can be shaped by both the mind and the senses.\n\n3. An illusion is a distortion of sensory perception that reveals how the mind normally organizes and interprets incoming information.\n\n4. Many illusions arise from the brain’s assumptions, perceptual principles, and biological structures, as well as from environmental conditions.\n\n5. The visual system, which includes the eyes and the central nervous system constructs reality through both perceptual and cognitive neural pathways.","answer":["5"],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (68).png","topperAttemptPercent":87.8},"area":"Verbal Reasoning","topic":"Odd sentence"}]}]},{"code":"DILR","groups":[{"id":"ims-simcat-2-2026-dilr-g01","title":"Music academy","questions":[{"id":"ims-simcat-2-2026-dilr-q01","sourceNumber":1,"type":"MCQ","prompt":"Which two instructors have saxophones as one of the instruments in their respective rooms?","answer":"D","options":[{"id":"A","text":"Nisha and Dev"},{"id":"B","text":"Arjun and Dev"},{"id":"C","text":"Meera and Nisha"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (69).png","topperAttemptPercent":99,"topperAccuracyPercent":97.17,"topperTimeSeconds":364,"topperPValue":96.2},"area":"Logical Reasoning","topic":"Music academy"},{"id":"ims-simcat-2-2026-dilr-q02","sourceNumber":2,"type":"MCQ","prompt":"Which instructor manages Room E?","answer":"C","options":[{"id":"A","text":"Arjun"},{"id":"B","text":"Tara"},{"id":"C","text":"Dev"},{"id":"D","text":"Nisha"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (70).png","topperAttemptPercent":99.4,"topperAccuracyPercent":99.2,"topperTimeSeconds":28,"topperPValue":98.6},"area":"Logical Reasoning","topic":"Music academy"},{"id":"ims-simcat-2-2026-dilr-q03","sourceNumber":3,"type":"MCQ","prompt":"Which instruments are in the room managed by Meera?","answer":"B","options":[{"id":"A","text":"Tabla and Saxophone"},{"id":"B","text":"Tabla and Violin"},{"id":"C","text":"Tabla and Guitar"},{"id":"D","text":"Tabla and Piano"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (71).png","topperAttemptPercent":99.2,"topperAccuracyPercent":98.59,"topperTimeSeconds":35,"topperPValue":97.8},"area":"Logical Reasoning","topic":"Music academy"},{"id":"ims-simcat-2-2026-dilr-q04","sourceNumber":4,"type":"MCQ","prompt":"Which two rooms have the same pair of instruments?","answer":"B","options":[{"id":"A","text":"Nisha's room and Arjun’s room"},{"id":"B","text":"Meera’s room and Tara’s room"},{"id":"C","text":"Dev’s room and Meera’s room"},{"id":"D","text":"Arjun’s room and Meera’s room"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (72).png","topperAttemptPercent":99,"topperAccuracyPercent":99.39,"topperTimeSeconds":25,"topperPValue":98.4},"area":"Logical Reasoning","topic":"Music academy"},{"id":"ims-simcat-2-2026-dilr-q05","sourceNumber":5,"type":"MCQ","prompt":"What is the pair of instruments in room A?","answer":"D","options":[{"id":"A","text":"Piano and Saxophone"},{"id":"B","text":"Tabla and Violin"},{"id":"C","text":"Guitar and Piano"},{"id":"D","text":"Cannot be determined"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (73).png","topperAttemptPercent":98.4,"topperAccuracyPercent":93.09,"topperTimeSeconds":42,"topperPValue":91.6},"area":"Logical Reasoning","topic":"Music academy"}],"stimulus":"There are ten musical instruments: two each of guitars, violins, tablas, pianos, and saxophones in a music academy. The five rooms in the academy are labelled A, B, C, D and E, and each is assigned to one of the following instructors: Nisha, Arjun, Dev, Tara, and Meera. Two instruments of different types are placed in each room. The following conditions are known\n\n1. A guitar and a tabla cannot be placed in the same room.\n\n2. Dev does not manage any room that contains a guitar, tabla, or violin.\n\n3. Rooms A, B, and C are assigned to Nisha, Meera, and Arjun respectively.\n\n4. Rooms B and D contain the same pair of instruments.\n\n5. Meera’s room contains a tabla."},{"id":"ims-simcat-2-2026-dilr-g06","title":"Eco-Blocks processing plants","questions":[{"id":"ims-simcat-2-2026-dilr-q06","sourceNumber":6,"type":"MCQ","prompt":"What is the ratio of the total weight of Glass used across all four plants combined to the total weight of Ash used across all four plants combined?","answer":"B","options":[{"id":"A","text":"45:43"},{"id":"B","text":"657 : 638"},{"id":"C","text":"112:105"},{"id":"D","text":"721:690"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (74).png","topperAttemptPercent":52.6,"topperAccuracyPercent":92.02,"topperTimeSeconds":429,"topperPValue":48.4},"area":"Data Interpretation","topic":"Eco-Blocks processing plants"},{"id":"ims-simcat-2-2026-dilr-q07","sourceNumber":7,"type":"MCQ","prompt":"If Gamma’s total raw material intake and material composition remain unchanged, approximately by how many percentage points must its processing-loss percentage be increased so that the proportion of Glass used in raw material relative to its own Total Output becomes equal to that of Delta?","answer":"C","options":[{"id":"A","text":"12.5 percentage points"},{"id":"B","text":"15 percentage points"},{"id":"C","text":"18.57 percentage points"},{"id":"D","text":"20 percentage points"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (75).png","topperAttemptPercent":36.4,"topperAccuracyPercent":85.16,"topperTimeSeconds":88,"topperPValue":31},"area":"Data Interpretation","topic":"Eco-Blocks processing plants"},{"id":"ims-simcat-2-2026-dilr-q08","sourceNumber":8,"type":"TITA","prompt":"If the total weight of Ash used in Gamma is 450 tons, what is the absolute difference between the total Plastic used in Delta and the total Glass used in Alpha in tons?","answer":["15"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (76).png","topperAttemptPercent":56,"topperAccuracyPercent":70.71,"topperTimeSeconds":56,"topperPValue":39.6},"area":"Data Interpretation","topic":"Eco-Blocks processing plants"},{"id":"ims-simcat-2-2026-dilr-q09","sourceNumber":9,"type":"MCQ","prompt":"Which plant utilizes the highest proportion of Glass relative to its own Total Output?","answer":"D","options":[{"id":"A","text":"Alpha"},{"id":"B","text":"Beta"},{"id":"C","text":"Gamma"},{"id":"D","text":"Delta"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (77).png","topperAttemptPercent":55.8,"topperAccuracyPercent":81.72,"topperTimeSeconds":62,"topperPValue":45.6},"area":"Data Interpretation","topic":"Eco-Blocks processing plants"}],"stimulus":"Omni Build Inc. manufactures \"Eco-Blocks\" using a blend of three recycled raw materials: Plastic (P), Glass (G), and Ash (A). The company operates four distinct processing plants: Alpha, Beta, Gamma, and Delta. During the thermal binding process at each plant, a certain percentage of the Total Raw Material weight is lost to evaporation and burn-off. This is known as the Processing Loss. Total weight of the Output (Weight of Eco-Blocks) = Total weight of the Raw Material - weight of the Processing Loss (Note: Total weight of raw material is equal to sum of weights of Plastic, Glass and Ash). The data chart below provides two parameters for each plant:\n\n1. Plastic Content %: The weight of Plastic used as a percentage of the Total Raw Material used.\n\n2. Processing Loss %: The weight lost during thermal binding as a percentage of the Total Raw Material used.\n\nProcessing plant | Plastic content (% of total raw material) | Processing loss (% of total raw material)\nAlpha | 40% | 20%\nBeta | 30% | 25%\nGamma | 50% | 10%\nDelta | 25% | 20%\n\nAdditional Information:\n\n1. The ratio of the Total Output of Alpha to the Total Output of Beta is 16 : 15.\n\n2. The weight of Plastic used in Gamma is exactly equal to the Total Raw Material used in Beta.\n\n3. The Total Output of Delta is exactly equal to the Total Raw Material used in Beta.\n\n4. In Alpha, the weight of Glass used is equal to the weight of Ash used.\n\n5. In Beta, Glass constitutes 40% of the non-plastic raw material used.\n\n6. In Gamma, the ratio of Glass to Ash used is 5: 3.\n\n7. In Delta, the ratio of Glass to Ash used is 7:8.","assetIds":["eco-blocks-table"]},{"id":"ims-simcat-2-2026-dilr-g10","title":"Shipping yard loading lanes","questions":[{"id":"ims-simcat-2-2026-dilr-q10","sourceNumber":10,"type":"MCQ","prompt":"Consider the following numbers: 135.5, 143.5, 144.5,152.5. How many of these numbers can be the mean of the numbers written in L3?","answer":"D","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"All 4"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (78).png","topperAccuracyPercent":72.33,"topperTimeSeconds":249,"topperPValue":23,"topperAttemptPercent":31.8},"area":"Logical Reasoning","topic":"Shipping yard loading lanes"},{"id":"ims-simcat-2-2026-dilr-q11","sourceNumber":11,"type":"MCQ","prompt":"What can be said about the sum of the numbers written in L1 and L2?","answer":"C","options":[{"id":"A","text":"The sum is definitely equal to 2550."},{"id":"B","text":"The sum is definitely equal to 2748."},{"id":"C","text":"The sum definitely lies between 2550 and 2748 (both inclusive)."},{"id":"D","text":"The sum can be either less than 2550 or greater than 2748."}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (79).png","topperAttemptPercent":28.2,"topperAccuracyPercent":84.4,"topperTimeSeconds":57,"topperPValue":23.8},"area":"Logical Reasoning","topic":"Shipping yard loading lanes"},{"id":"ims-simcat-2-2026-dilr-q12","sourceNumber":12,"type":"TITA","prompt":"If A= Maximum possible sum of the numbers written in L5 and B = Minimum possible sum of the numbers written in L5. What is the value of A— B?","answer":["184"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (80).png","topperAccuracyPercent":46.34,"topperTimeSeconds":43,"topperAttemptPercent":32.8,"topperPValue":15.2},"area":"Logical Reasoning","topic":"Shipping yard loading lanes"},{"id":"ims-simcat-2-2026-dilr-q13","sourceNumber":13,"type":"TITA","prompt":"What is the sum of all the numbers written on the six lanes taken together? (Write 0 if your answer is ‘Cannot be determined’)","answer":["7670"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (81).png","topperAccuracyPercent":52.75,"topperTimeSeconds":45,"topperPValue":19.2,"topperAttemptPercent":36.4},"area":"Logical Reasoning","topic":"Shipping yard loading lanes"}],"stimulus":"A shipping yard has six loading lanes named L1, L2, L3, L4, L5, and L6. Each lane contains crates arranged in a row, and the numbers of crates in the six lanes are all different natural numbers greater than 6. Mira decides to assign a natural number to each crate. She chooses one lane and numbers the crates in that lane from the left end to the right end using consecutive natural numbers, not necessarily starting from 1. After finishing that lane, she chooses another lane and numbers its crates from left to right, again using consecutive natural numbers, such that the number assigned to the left-most crate of the new lane is the immediate successor of the number assigned to the right-most crate of the previous lane. She continues in this way until all crates in all six lanes have been numbered. After numbering all the crates, she observes the following:\n\n1. The total number of crates in all six lanes is 59.\n\n2.L3 contains twice as many crates as L6.\n\n3.L1 contains 3 more crates than L5.\n\n4. The lane with the fewest crates was numbered first.\n\n5. The first crate numbered in L6 received the number 101.\n\n6. The mean of the numbers written in L4 is 112.5.\n\n7. The mean of the numbers written in L1 is 123."},{"id":"ims-simcat-2-2026-dilr-g14","title":"Welham Public School","questions":[{"id":"ims-simcat-2-2026-dilr-q14","sourceNumber":14,"type":"TITA","prompt":"How many students enrolled in the class of the ‘original students’ as fresh admissions in 2025 in class X?","answer":["20"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (82).png","topperAttemptPercent":34.2,"topperAccuracyPercent":34.5,"topperTimeSeconds":183,"topperPValue":11.8},"area":"Data Interpretation","topic":"Welham Public School"},{"id":"ims-simcat-2-2026-dilr-q15","sourceNumber":15,"type":"MCQ","prompt":"Among the ‘original students’ who appeared in the 10th Board Examination in 2026, the number of boys exceeded the number of girls by ______ %.","answer":"C","options":[{"id":"A","text":"12 1/2"},{"id":"B","text":"14 1/7"},{"id":"C","text":"16 1/6"},{"id":"D","text":"Multiple answers are possible"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (83).png","topperAttemptPercent":13.6,"topperAccuracyPercent":58.82,"topperTimeSeconds":37,"topperPValue":8},"area":"Data Interpretation","topic":"Welham Public School"},{"id":"ims-simcat-2-2026-dilr-q16","sourceNumber":16,"type":"MCQ","prompt":"Among the students of class VIII in 2023-24 session, find the value of the ratio of - (no. of students from ‘original students’) : (no. of students from fresh admission in 2022).","answer":"D","options":[{"id":"A","text":"8:1"},{"id":"B","text":"25:3"},{"id":"C","text":"35:4"},{"id":"D","text":"32:3"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (84).png","topperAttemptPercent":15,"topperAccuracyPercent":85.33,"topperTimeSeconds":32,"topperPValue":12.8},"area":"Data Interpretation","topic":"Welham Public School"},{"id":"ims-simcat-2-2026-dilr-q17","sourceNumber":17,"type":"TITA","prompt":"The number of girls initially present in the ‘original students’ group in 2021 was 16 more than the number of girls who appeared from the group in the 10th Board Examination in\n\n2026. How many boys were present in the ‘original students’ group in 2021?","answer":["204"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (85).png","topperAttemptPercent":23,"topperAccuracyPercent":33.91,"topperTimeSeconds":26,"topperPValue":7.8},"area":"Data Interpretation","topic":"Welham Public School"},{"id":"ims-simcat-2-2026-dilr-q18","sourceNumber":18,"type":"TITA","prompt":"In the academic session of 2023-24, when the “original students” were in class VIII, the number of girls and boys were equal in that class. What is the minimum number of girls enrolled in class VII in 2022 as fresh admission?","answer":["17"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (86).png","topperTimeSeconds":35,"topperAttemptPercent":21.8,"topperAccuracyPercent":16.51,"topperPValue":3.6},"area":"Data Interpretation","topic":"Welham Public School"}],"stimulus":"Welham Public School has a long-standing reputation for producing excellent academic results. The school maintains a disciplined environment with strict rules and a strong emphasis on academic performance. The academic session runs annually from March to February of the following year. Students who do not pass the annual examination are required to leave the school, and the resulting vacancies are filled through fresh admissions so that the class strength remains unchanged. No student leaves the school for a reason other than failing in the annual examination. Each year, exactly 340 students from the school appear for the 10th Board Examination. In fact, the school maintains a class strength of 340 students in each grade from Class VI onward. A group of educational psychologists is studying the students who were already in the school in 2021 and later appeared for the 10th Board Examination in 2026. These students are referred to as the ‘original students’. The bar graph below shows the number of fresh admissions made in the class of the original students in different grades and years.\n\nFresh admissions (bar graph):\nClass VII in 2022: 32\nClass VIII in 2023: 25\nClass IX in 2024: 20\n\nNumber of fresh-admission students who later failed and could not be promoted:\nAdmission cohort | To class VIII | To class IX | To class X\nClass VII in 2022 | 5 | 2 | 0\nClass VIII in 2023 | — | 5 | 2\nClass IX in 2024 | — | — | 3\n\nThe following facts are also known about these ‘original students’\n\n1. Each year at least one girl and one boy among the ‘original students’ failed to pass the annual examination.\n\n2. Among the ‘original students’, more boys than girls left the school each year.\n\n3. Only 260 ‘original students’ appeared in the 10th Board Examination in 2026. The remaining are fresh admissions because of vacancies created from 2022 to 2025.\n\n4) Among the ‘original students’ who were promoted to class VII in 2022, the number of boys was 33 1/3% more than that of the girls.\n\n5) Among the ‘original students’, the ratio of the number of girls to the number of boys in class VIII was 4: 5, and in class IX was 5 : 6. The corresponding ratio in class X was n : (n+ 1), where n is a single digit natural number.","assetIds":["school-admissions-chart","school-failures-table"]},{"id":"ims-simcat-2-2026-dilr-g19","title":"Hong Kong Super Five team","questions":[{"id":"ims-simcat-2-2026-dilr-q19","sourceNumber":19,"type":"MCQ","prompt":"Which of the following groups of players can form a valid team?","answer":"C","options":[{"id":"A","text":"Sujata, Sumaya, Sunita, Suprita, Supriya"},{"id":"B","text":"Sanjana, Sarita, Savita, Sujata, Sumaya"},{"id":"C","text":"Sanjana, Sarita, Sujata, Sumaya, Suprita"},{"id":"D","text":"Sarita, Savita, Sumaya, Suprita, Supriya"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (87).png","topperAccuracyPercent":97.96,"topperPValue":96.2,"topperAttemptPercent":98.2,"topperTimeSeconds":242},"area":"Logical Reasoning","topic":"Hong Kong Super Five team"},{"id":"ims-simcat-2-2026-dilr-q20","sourceNumber":20,"type":"MCQ","prompt":"Which of the following players must be selected in every valid team?","answer":"D","options":[{"id":"A","text":"Supriya"},{"id":"B","text":"Sumaya"},{"id":"C","text":"Savita"},{"id":"D","text":"Sujata"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (88).png","topperAttemptPercent":98.4,"topperAccuracyPercent":95.73,"topperTimeSeconds":108,"topperPValue":94.2},"area":"Logical Reasoning","topic":"Hong Kong Super Five team"},{"id":"ims-simcat-2-2026-dilr-q21","sourceNumber":21,"type":"MCQ","prompt":"If Supriya is selected in the team, which of the following statements can be true?\n\nI. Sumaya is selected.\nII. Savita is selected.\nIII. Sunita is selected.","answer":"B","options":[{"id":"A","text":"Only I"},{"id":"B","text":"Only III"},{"id":"C","text":"Only I and III"},{"id":"D","text":"All I, II and III"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (90).png","topperAttemptPercent":97.6,"topperAccuracyPercent":95.08,"topperTimeSeconds":100,"topperPValue":92.8},"area":"Logical Reasoning","topic":"Hong Kong Super Five team"},{"id":"ims-simcat-2-2026-dilr-q22","sourceNumber":22,"type":"MCQ","prompt":"If Sunita is already selected, which of the following groups of four players can be selected along with her?","answer":"A","options":[{"id":"A","text":"Supriya, Sanjana, Sujata and Suprita"},{"id":"B","text":"Sumaya, Sanjana, Sujata and Savita"},{"id":"C","text":"Supriya, Sumaya, Savita and Sujata"},{"id":"D","text":"Supriya Sanjana, Sarita and Suprita"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (91).png","topperAttemptPercent":97.4,"topperAccuracyPercent":95.07,"topperPValue":92.6,"topperTimeSeconds":110},"area":"Logical Reasoning","topic":"Hong Kong Super Five team"}],"stimulus":"A 5-member cricket team has to be selected for a new format of cricket named Hong Kong Super Five! It must be composed of 2 batters, 2 bowlers and one wicketkeeper. There are three batting contenders: Supriya, Sumaya and Sanjana. There are two wicketkeeping contenders: Sunita and Sarita. There are three bowling contenders: Savita, Sujata and Suprita. Following conditions are known:\n\n1. If Savita is selected, then Suprita cannot be selected.\n\n2. If Sanjana is selected, then Savita cannot be selected.\n\n3. If Sumaya is selected, then Sanjana must also be selected."}]},{"code":"QA","groups":[{"id":"ims-simcat-2-2026-qa-g01","title":"Geometry · Q1","questions":[{"id":"ims-simcat-2-2026-qa-q01","sourceNumber":1,"type":"MCQ","prompt":"ABCD is a rhombus (AC > BD) with O being the point of intersection of its two diagonals. The area and the perimeter of the rhombus are 96 sq. cm and 40 cm, respectively. E is a point on AD (A-E-D), F is a point on AO (A-F-O), and G is a point on OD (O-G-D). It is known that AE = DG = 4cm, and OF = 6cm. Find the area (in cm²) of the triangle EFG.","answer":"C","options":[{"id":"A","text":"4.8"},{"id":"B","text":"5"},{"id":"C","text":"6"},{"id":"D","text":"8"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (92).png","topperAttemptPercent":25.6,"topperAccuracyPercent":80.47,"topperTimeSeconds":144},"area":"Geometry","topic":"Geometry · Q1"}]},{"id":"ims-simcat-2-2026-qa-g02","title":"Geometry · Q2","questions":[{"id":"ims-simcat-2-2026-qa-q02","sourceNumber":2,"type":"TITA","prompt":"A solid sphere has radius N cm, where N is a natural number. If its radius is increased by 1 cm, the increase in volume is V cu.cm and the increase in surface area is A sq. cm. Find the minimum value of N such that numerically V ≥ 10A.","answer":["20"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (93).png","topperAttemptPercent":36.8},"area":"Geometry","topic":"Geometry · Q2"}]},{"id":"ims-simcat-2-2026-qa-g03","title":"Algebra · Q3","questions":[{"id":"ims-simcat-2-2026-qa-q03","sourceNumber":3,"type":"MCQ","prompt":"Evaluate √(60 + 12√6 − 12√(25 + 10√6)).","answer":"A","options":[{"id":"A","text":"2√3 + 3√2 − √30"},{"id":"B","text":"3√2 − 2√3 + √30"},{"id":"C","text":"2√3 − 3√2 + √30"},{"id":"D","text":"2√3 − 3√2 − √30"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (94).png","topperAttemptPercent":51.8,"topperAccuracyPercent":78.38,"topperTimeSeconds":145,"topperPValue":40.6},"area":"Algebra","topic":"Algebra · Q3"}]},{"id":"ims-simcat-2-2026-qa-g04","title":"Arithmetic · Q4","questions":[{"id":"ims-simcat-2-2026-qa-q04","sourceNumber":4,"type":"MCQ","prompt":"A shopkeeper offers a \"Buy 5 Get 4 Free\" scheme. Additionally, he allows a 20% discount to a loyal customer. If he still makes a profit of 25%, by what percentage was the marked price above the cost price?","answer":"B","options":[{"id":"A","text":"125.25%"},{"id":"B","text":"181.25%"},{"id":"C","text":"150%"},{"id":"D","text":"133.33%"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (95).png","topperAttemptPercent":88.6,"topperAccuracyPercent":96.16,"topperTimeSeconds":158,"topperPValue":85.2},"area":"Arithmetic","topic":"Arithmetic · Q4"}]},{"id":"ims-simcat-2-2026-qa-g05","title":"Algebra · Q5","questions":[{"id":"ims-simcat-2-2026-qa-q05","sourceNumber":5,"type":"MCQ","prompt":"If α, β, θ and π are the four real roots of 120x⁴ − 326x³ + 329x² − 146x + 24 = 0 and\n\nn = [1/(αβθ + βθπ + θπα + παβ)] × [1/(αβθ) + 1/(βθπ) + 1/(θπα) + 1/(παβ)],\n\nthen find the smallest integer larger than or equal to n.","answer":"C","options":[{"id":"A","text":"10"},{"id":"B","text":"11"},{"id":"C","text":"12"},{"id":"D","text":"13"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (96).png","topperAttemptPercent":30.6,"topperAccuracyPercent":83.01,"topperTimeSeconds":78},"area":"Algebra","topic":"Algebra · Q5"}]},{"id":"ims-simcat-2-2026-qa-g06","title":"Algebra · Q6","questions":[{"id":"ims-simcat-2-2026-qa-q06","sourceNumber":6,"type":"TITA","prompt":"If f(x) = max{|x − 2| + 3, 11 − x}, where ‘x’ is a real number. What is the minimum value of f(x)?","answer":["6"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (97).png","topperAttemptPercent":61.8,"topperAccuracyPercent":82.52,"topperTimeSeconds":74},"area":"Algebra","topic":"Algebra · Q6"}]},{"id":"ims-simcat-2-2026-qa-g07","title":"Algebra · Q7","questions":[{"id":"ims-simcat-2-2026-qa-q07","sourceNumber":7,"type":"MCQ","prompt":"Let f₁(x) = 2x + 1, f₂(x) = x − 4 and f₃(x) = (x + 7)/2. Find the value of f₁(f₂(f₃(f₁(f₂(f₃(2026)))))).","answer":"C","options":[{"id":"A","text":"2027/2"},{"id":"B","text":"2025/2"},{"id":"C","text":"2026"},{"id":"D","text":"4053"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (98).png","topperAttemptPercent":72.4,"topperAccuracyPercent":98.07,"topperTimeSeconds":76},"area":"Algebra","topic":"Algebra · Q7"}]},{"id":"ims-simcat-2-2026-qa-g08","title":"Geometry · Q8","questions":[{"id":"ims-simcat-2-2026-qa-q08","sourceNumber":8,"type":"MCQ","prompt":"A landscape architect is designing a right-angled triangular flower bed. She is constrained by the design to ensure the longest side (the hypotenuse) measures exactly H metres, and the total perimeter of the flower bed measures exactly P metres. Which of the following expressions represents the total enclosed area of the flower bed?","answer":"B","options":[{"id":"A","text":"(P² − H²)/4"},{"id":"B","text":"(P² − 2PH)/4"},{"id":"C","text":"(P² + 2PH)/2"},{"id":"D","text":"(P² − 4H²)/8"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (99).png","topperAttemptPercent":63.4},"area":"Geometry","topic":"Geometry · Q8"}]},{"id":"ims-simcat-2-2026-qa-g09","title":"Arithmetic · Q9","questions":[{"id":"ims-simcat-2-2026-qa-q09","sourceNumber":9,"type":"MCQ","prompt":"The maximum volume of liquid that a vessel can contain is 100 litres. The vessel initially contains 50 litres of milk. A milkman performs 100 rounds of operations on this milk. In the first round, he adds water so that half of the remaining empty space of the vessel gets filled. In the second round, he adds milk so that half of the remaining empty space of the vessel gets filled. In the third round, he again adds water so that half of the remaining empty space of the vessel gets filled, and so on. After the 99th round the ratio of milk to water (by volume) in the vessel will be ______.","answer":"B","options":[{"id":"A","text":"3 : 1"},{"id":"B","text":"2 : 1"},{"id":"C","text":"(2 + 0.25^99) : 1"},{"id":"D","text":"(2 + 0.25^49) : 1"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (100).png","topperAttemptPercent":51.6},"area":"Arithmetic","topic":"Arithmetic · Q9"}]},{"id":"ims-simcat-2-2026-qa-g10","title":"Number System · Q10","questions":[{"id":"ims-simcat-2-2026-qa-q10","sourceNumber":10,"type":"TITA","prompt":"The largest term common to the sequences 5, 17, 29, 41, ... up to 120 terms and 41, 50, 59, 68, ... up to 120 terms is ______.","answer":["1085"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (101).png","topperAttemptPercent":78.6,"topperAccuracyPercent":69.21},"area":"Number System","topic":"Number System · Q10"}]},{"id":"ims-simcat-2-2026-qa-g11","title":"Arithmetic · Q11","questions":[{"id":"ims-simcat-2-2026-qa-q11","sourceNumber":11,"type":"MCQ","prompt":"Elena deposits $68,000 into a business savings account that offers a 6% per annum interest rate. At the end of every 3 months, she withdraws $17,000 from this account to pay for software licenses and quarterly taxes. For each quarter, interest is calculated only on the principal outstanding at the beginning of that quarter. The interest earned in one quarter is not added to the principal for the purpose of calculating interest in the next quarter. Calculate the total amount of interest Elena will have earned at the end of 12 months.","answer":"C","options":[{"id":"A","text":"$1,700"},{"id":"B","text":"$3,400"},{"id":"C","text":"$2,550"},{"id":"D","text":"$4,220"}],"selectionCategory":"A","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (102).png","topperAttemptPercent":72.4,"topperAccuracyPercent":95.3,"topperTimeSeconds":143},"area":"Arithmetic","topic":"Arithmetic · Q11"}]},{"id":"ims-simcat-2-2026-qa-g12","title":"Algebra · Q12","questions":[{"id":"ims-simcat-2-2026-qa-q12","sourceNumber":12,"type":"MCQ","prompt":"How many integer values of ‘m’ can be written in the form m = k² − 12k, where the equation x² − (k + 3)x + 4k = 0 has two distinct real roots in the ratio 2 : 1?","answer":"B","options":[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"2"},{"id":"D","text":"4"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (103).png","topperAttemptPercent":60,"topperAccuracyPercent":79.67,"topperTimeSeconds":124,"topperPValue":47.8},"area":"Algebra","topic":"Algebra · Q12"}]},{"id":"ims-simcat-2-2026-qa-g13","title":"Algebra · Q13","questions":[{"id":"ims-simcat-2-2026-qa-q13","sourceNumber":13,"type":"MCQ","prompt":"If ‘P’ is a positive real number such Sₘ ≤ P ≤ Sₘ₊₁, where Sₙ is the sum of first ‘n’ terms of the sequence 1, 6/11, 10/11², 14/11³, 18/11⁴, …, the value of P cannot be ______.","answer":"D","options":[{"id":"A","text":"3/2"},{"id":"B","text":"59/50"},{"id":"C","text":"71/50"},{"id":"D","text":"83/50"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (104).png","topperAttemptPercent":24.2,"topperAccuracyPercent":82.64,"topperTimeSeconds":64},"area":"Algebra","topic":"Algebra · Q13"}]},{"id":"ims-simcat-2-2026-qa-g14","title":"Modern Mathematics · Q14","questions":[{"id":"ims-simcat-2-2026-qa-q14","sourceNumber":14,"type":"TITA","prompt":"How many paths are there from the origin (0, 0) to the point (6, 6), moving only one unit at a time either to the right or upward, that do not pass through the point (3, 3)?","answer":["524"],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (105).png","topperAttemptPercent":39.2,"topperAccuracyPercent":60.71},"area":"Modern Mathematics","topic":"Modern Mathematics · Q14"}]},{"id":"ims-simcat-2-2026-qa-g15","title":"Arithmetic · Q15","questions":[{"id":"ims-simcat-2-2026-qa-q15","sourceNumber":15,"type":"TITA","prompt":"Two cars, a faster car and a slower car start at the exact same time from two different points. If they move directly towards each other, they meet after exactly 4 hours. If they move in the same direction (with the faster car chasing after the slower car), it takes the faster car exactly 12 hours to catch up with the slower car. If the slower car moves at a steady speed of 45 km/hr, what is the speed of the faster car in km/hr?","answer":["90"],"selectionCategory":"A","area":"Arithmetic","topic":"Arithmetic · Q15"}]},{"id":"ims-simcat-2-2026-qa-g16","title":"Number System · Q16","questions":[{"id":"ims-simcat-2-2026-qa-q16","sourceNumber":16,"type":"TITA","prompt":"The last two digits of (6^100 + 7^100) are ______.","answer":["77"],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (107).png","topperAttemptPercent":73.6,"topperAccuracyPercent":61.96,"topperTimeSeconds":102},"area":"Number System","topic":"Number System · Q16"}]},{"id":"ims-simcat-2-2026-qa-g17","title":"Arithmetic · Q17","questions":[{"id":"ims-simcat-2-2026-qa-q17","sourceNumber":17,"type":"TITA","prompt":"Four software developers Alice, Bob, Charlie, and Diana are building a new mobile app together. They agree to divide the work and contribute to the total coding work in the ratio 2: 3:4: 1, respectively. If they were to code the entire app completely alone from scratch, it would take them 5, 10, 15, and 20 days, respectively. If they work on the app one after the other (sequentially) to complete their assigned shares, how many total days will it take to finish the app?","answer":["12"],"selectionCategory":"A","area":"Arithmetic","topic":"Arithmetic · Q17"}]},{"id":"ims-simcat-2-2026-qa-g18","title":"Geometry · Q18","questions":[{"id":"ims-simcat-2-2026-qa-q18","sourceNumber":18,"type":"MCQ","prompt":"The coordinates of the vertices of △ABC are A (0, 3), B (0, 0), and C (4, 0). Given BD ⟂ AC such that A-D-C. Find the coordinates of point D.","answer":"B","options":[{"id":"A","text":"(1.56, 1.88)"},{"id":"B","text":"(1.44, 1.92)"},{"id":"C","text":"(1.44, 1.76)"},{"id":"D","text":"(2.56, 1.92)"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (109).png","topperAttemptPercent":43.6,"topperAccuracyPercent":93.12,"topperTimeSeconds":101,"topperPValue":40.6},"area":"Geometry","topic":"Geometry · Q18"}]},{"id":"ims-simcat-2-2026-qa-g19","title":"Algebra · Q19","questions":[{"id":"ims-simcat-2-2026-qa-q19","sourceNumber":19,"type":"MCQ","prompt":"Let ‘x’ and ‘y’ be the integers greater than 1 satisfying 2x + 3y ≤ 12, x − y ≥ 1, x + y ≥ 4. What is the maximum possible value of (3x + 2y)?","answer":"D","options":[{"id":"A","text":"10"},{"id":"B","text":"11"},{"id":"C","text":"12"},{"id":"D","text":"13"}],"selectionCategory":"B","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (110).png","topperAttemptPercent":57.4,"topperAccuracyPercent":90.24,"topperTimeSeconds":82,"topperPValue":51.8},"area":"Algebra","topic":"Algebra · Q19"}]},{"id":"ims-simcat-2-2026-qa-g20","title":"Number System · Q20","questions":[{"id":"ims-simcat-2-2026-qa-q20","sourceNumber":20,"type":"MCQ","prompt":"If 24^n is a factor of (100!)²/(40!)³, the highest value ‘n’ can take is ______.","answer":"C","options":[{"id":"A","text":"24"},{"id":"B","text":"25"},{"id":"C","text":"26"},{"id":"D","text":"28"}],"selectionCategory":"C","benchmark":{"source":"IMS supplied review screenshots","sourceImage":"Screenshot (111).png","topperAttemptPercent":28.4,"topperAccuracyPercent":78.87,"topperTimeSeconds":69,"topperPValue":22.4},"area":"Number System","topic":"Number System · Q20"}]},{"id":"ims-simcat-2-2026-qa-g21","title":"Number System · Q21","questions":[{"id":"ims-simcat-2-2026-qa-q21","sourceNumber":21,"type":"TITA","prompt":"On an alien planet, numbers are written in the octal system, using digits 0 to 7 instead of the decimal system used on Earth. Mr. Bean visits the planet and sees two house numbers 257 and 346. A local guide tells him that the lucky house is the one whose number is equal to the sum of these two house numbers. What is the decimal value of the lucky house number?","answer":["405"],"selectionCategory":"C","area":"Number System","topic":"Number System · Q21"}]},{"id":"ims-simcat-2-2026-qa-g22","title":"Arithmetic · Q22","questions":[{"id":"ims-simcat-2-2026-qa-q22","sourceNumber":22,"type":"TITA","prompt":"Three remote control cars Red, Blue, and Green are raced over a track of D metres. All cars maintain a constant speed throughout the race. The Red car beats the Blue car by 40 metres. The Red car beats the Green car by 76 metres. If the Blue car and Green cars run the same race against each other, the Blue car beats the Green car by 40 metres. Find the total length of the race track in meters.","answer":["400"],"selectionCategory":"B","area":"Arithmetic","topic":"Arithmetic · Q22"}]}]}],"assets":{"eco-blocks-table":{"alt":"Original processing-plant table; the values are also transcribed above.","data":"data:image/png;base64,"},"school-admissions-chart":{"alt":"Fresh admissions: Class VII 2022, 32; Class VIII 2023, 25; Class IX 2024, 20.","data":"data:image/png;base64,"},"school-failures-table":{"alt":"Original table of fresh-admission students failing promotion; the values are transcribed above.","data":"data:image/png;base64,"}}},{"schemaVersion":1,"testType":"full","id":"cat-studio-demo","revision":1,"title":"Explore the exam experience","demo":true,"description":"A short, original sample across all three sections. Try the tools before a real attempt.","sections":[{"code":"VARC","groups":[{"id":"demo-rc","title":"RC · Learning through retrieval","stimulus":"Students often judge learning by how familiar a page feels on a second reading. Yet familiarity can conceal gaps in recall. A learner who closes the book and tries to explain an idea may feel less fluent, but the effort reveals what remains uncertain.\n\nThis does not make rereading useless. A return to the text after an attempted explanation can target specific gaps. The distinction is between rereading to avoid effort and rereading to answer a question that effort has exposed.","questions":[{"id":"demo-v1","type":"MCQ","prompt":"Which statement best captures the central argument?","options":[{"id":"A","text":"Rereading always harms recall."},{"id":"B","text":"Fluency is a reliable measure of understanding."},{"id":"C","text":"Attempting recall can reveal gaps that targeted rereading then addresses."},{"id":"D","text":"Books should be closed permanently after one reading."}],"answer":"C","topic":"Reading comprehension","explanation":"The author combines effortful recall with targeted rereading rather than rejecting rereading."},{"id":"demo-v2","type":"MCQ","prompt":"The author would most likely recommend:","options":[{"id":"A","text":"Explaining an idea without the text, then checking uncertain points."},{"id":"B","text":"Reading a page until every word feels familiar."},{"id":"C","text":"Avoiding difficult explanations."},{"id":"D","text":"Measuring learning only by reading speed."}],"answer":"A","topic":"Reading comprehension","explanation":"This sequence follows the method described in the second paragraph."}]},{"id":"demo-va","title":"Verbal ability","questions":[{"id":"demo-v3","type":"TITA","prompt":"Arrange the sentences into a coherent paragraph. Enter the sequence.\n\n1. This stored water supports the seedlings during dry weeks.\n2. Farmers first collect rainwater in small tanks.\n3. They then channel the stored water towards newly planted beds.","answer":["231"],"topic":"Para jumble","explanation":"Collection comes first, channeling follows, and the final sentence explains the benefit."}]}]},{"code":"DILR","groups":[{"id":"demo-di","title":"DI · Bookshop sales","stimulus":"A bookshop sold the following numbers of books.\n\n             Monday   Tuesday\nFiction        30        45\nScience        20        25\nHistory        10        20\n\nAll figures are numbers of books, not sales revenue.","questions":[{"id":"demo-d1","type":"TITA","prompt":"How many books were sold on Tuesday?","answer":["90"],"topic":"Tables","explanation":"45 + 25 + 20 = 90."},{"id":"demo-d2","type":"MCQ","prompt":"Which category had the largest percentage increase from Monday to Tuesday?","options":[{"id":"A","text":"Fiction"},{"id":"B","text":"Science"},{"id":"C","text":"History"},{"id":"D","text":"All three were equal"}],"answer":"C","topic":"Tables","explanation":"History doubled from 10 to 20, an increase of 100%."},{"id":"demo-d3","type":"TITA","prompt":"What percentage of Monday sales consisted of fiction books?","answer":["50"],"topic":"Tables","explanation":"30 out of 60 books is 50%."}]}]},{"code":"QA","groups":[{"id":"demo-qa1","title":"Arithmetic","questions":[{"id":"demo-q1","type":"MCQ","prompt":"A price rises by 20% and then falls by 20%. What is the net change?","options":[{"id":"A","text":"No change"},{"id":"B","text":"4% decrease"},{"id":"C","text":"4% increase"},{"id":"D","text":"2% decrease"}],"answer":"B","topic":"Percentages","explanation":"100 × 1.2 × 0.8 = 96, a decrease of 4%."}]},{"id":"demo-qa2","title":"Algebra","questions":[{"id":"demo-q2","type":"TITA","prompt":"If 3x + 7 = 34, find x.","answer":["9"],"topic":"Linear equations","explanation":"Subtract 7 and divide by 3: x = 27 / 3 = 9."}]},{"id":"demo-qa3","title":"Arithmetic","questions":[{"id":"demo-q3","type":"MCQ","prompt":"A train covers 180 km in 3 hours. What is its average speed?","options":[{"id":"A","text":"45 km/h"},{"id":"B","text":"50 km/h"},{"id":"C","text":"60 km/h"},{"id":"D","text":"90 km/h"}],"answer":"C","topic":"Speed and distance","explanation":"Speed = distance / time = 180 / 3 = 60 km/h."}]}]}]}];
